/* ===MODULE:shiftSync=== */
RPGACE.register('shiftSync', {

  init: function() {
    var self = this;
    // Do NOT rely solely on rpgace:ready — it may have already fired before
    // this module's init() runs (confirmed failure mode from the taxonomy
    // detection build). Call directly with a delay instead, plus keep the
    // hook as a secondary path in case timing differs on some page loads.
    setTimeout(function() { self._syncFromSupabase(); }, 1200);

    RPGACE.hooks.on('page:show', function(name) {
      if (name === RPGACE.CONFIG.pages.schedule) {
        setTimeout(function() { self._syncFromSupabase(); }, 300);
      }
    });
  },

  _syncFromSupabase: function() {
    var self = this;
    RPGACE.sb.select('rpgace_shifts', 'order=date.asc&limit=200')
      .then(function(rows) {
        rows = rows || [];
        if (rows.length === 0) {
          console.log('[shiftSync] No shifts in Supabase yet');
        } else {
          var shifts = rows.map(function(r) {
            return { date: r.date, day: r.day, role: r.role, start: r.start, end: r.end, hours: r.hours };
          });
          // July 24 audit fix: routed through RPGACE.DB.get/set (rule 8 -
          // DB.SCHEMA already declares 'shifts' as this exact key) so
          // R.hooks.fire('db:change', ...) actually fires on this sync -
          // the raw localStorage call used to skip it silently.
          var before = RPGACE.DB.get('shifts').length;
          RPGACE.DB.set('shifts', shifts);
          console.log('[shiftSync] Synced ' + shifts.length + ' shifts from Supabase (was ' + before + ' in localStorage)');
          if (typeof window.autoApplyStoredShifts === 'function') window.autoApplyStoredShifts();
        }
        self._syncAgendasFromSupabase();
      })
      .catch(function(e) {
        console.warn('[shiftSync] Supabase shifts fetch failed:', e.message);
        self._syncAgendasFromSupabase();
      });
  },

  // ── Pulls scheduled agendas/tasks from Supabase into localStorage, same
  // ── cross-device pattern as shifts. Fixes tasks scheduled on one device
  // ── (e.g. phone) not appearing on another (e.g. desktop).
  _syncAgendasFromSupabase: function() {
    RPGACE.sb.select('rpgace_agendas', 'order=date.asc&limit=300')
      .then(function(rows) {
        rows = rows || [];
        RPGACE.DB.set('sched', rows); // July 24 audit fix - see shifts sync above, same reasoning
        console.log('[shiftSync] Synced ' + rows.length + ' agendas from Supabase');
        if (typeof window.buildMonthSlots === 'function') { try { window.buildMonthSlots(); } catch(e){} }
        if (typeof window.buildWeekSlots === 'function') { try { window.buildWeekSlots(); } catch(e){} }
        if (typeof window.renderDailyGrid === 'function') { try { window.renderDailyGrid(); } catch(e){} }
      })
      .catch(function(e) {
        console.warn('[shiftSync] Supabase agendas fetch failed:', e.message);
      });
  },

});
/* ===END:shiftSync=== */

/* ===MODULE:scheduleFixes=== */
// July 22, 2 real QoL bugs found by GODMODE evidence pass, both root-caused
// against real main.js source rather than guessed:
//
// 1) "Daily view is missing its ◄Prev/date/Next► nav on first load, only
//    appears after cycling through Weekly and back." Root cause:
//    showPage('schedule') never calls showSched() at all - it just leaves
//    whatever #sched-X div is already marked visible in static HTML on
//    screen, raw. Only an explicit showSched('daily') call runs
//    initDailyNav()/renderDailyGrid() (main.js, lines ~1960/~1848), which
//    is what actually builds the Prev/Next header. Fix: fire it once,
//    shortly after arriving at the Schedule page - the exact same call a
//    manual Daily-tab click already makes, just triggered automatically.
//
// 2) "Clicking Daily/Weekly gives XP, this needs to stop." Root cause:
//    showSched('daily'|'weekly') both schedule a call to
//    autoApplyStoredShifts() (main.js), which re-populates the grid from
//    already-stored shifts on every view - a pure redisplay, not a new
//    import. But it calls the SAME applyShifts() the real Import Shifts
//    flow uses, and applyShifts() unconditionally ends with addXP(30) -
//    so every single schedule view was re-awarding the one-time import
//    bonus. Can't edit applyShifts (main.js, frozen) to add a "skip XP"
//    flag without breaking real imports elsewhere. Fix: since
//    autoApplyStoredShifts() is fully synchronous (no await/promise),
//    wrap window.autoApplyStoredShifts to swap addXP to a no-op only for
//    the duration of that one synchronous call, then restore it - real
//    imports (parseICS/parseCSV/parseText → applyShifts, called directly,
//    never through this wrapper) are completely unaffected and still earn
//    their XP normally.
RPGACE.register('scheduleFixes', {

  init: function() {
    var self = this;
    self._patchAutoApply();
    RPGACE.registerBootTask(function() { return self._patchAutoApply(); });
    RPGACE.hooks.on('page:show', function(name) {
      if (name === RPGACE.CONFIG.pages.schedule) {
        setTimeout(function() { if (typeof window.showSched === 'function') window.showSched('daily'); }, 200);
      }
    });
  },

  _patchAutoApply: function() {
    if (typeof window.autoApplyStoredShifts !== 'function' || window._autoApplyXPPatched) return;
    window._autoApplyXPPatched = true;
    var orig = window.autoApplyStoredShifts;
    window.autoApplyStoredShifts = function() {
      var realAddXP = window.addXP;
      if (typeof realAddXP === 'function') window.addXP = function() {};
      try {
        return orig.apply(this, arguments);
      } finally {
        window.addXP = realAddXP;
      }
    };
  },

});
/* ===END:scheduleFixes=== */

/* ===MODULE:agentsIntoOracle=== */
// July 22 QoL request: "fold [Agents] into Oracle AI." GODMODE evidence
// pass first - the Agents page (main.js AGENT_ACTIONS + buildAgentActions())
// is real, not empty: 8 genuine one-click Composio actions with per-action
// XP, a connected-apps status bar, and an activity log. The actual
// complaint was 3 of those 8 actions overlapping with Oracle's own
// .quick-row buttons (draft email, YT stats, log to Notion) making a
// whole separate nav page feel redundant - not that the content itself
// was worthless. Council of 5 verdict: fold it in physically rather than
// rebuild it - buildAgentActions() (main.js, frozen) just does
// document.getElementById('agent-actions') and fills it, so it works
// regardless of where that element physically lives in the DOM. Reuses
// the exact "move live DOM nodes" pattern dashDeck already established
// for Bookworm/Knowledge Gaps/Content Pipeline (_stashWidget/_ensureStash) -
// just a one-way permanent move here, not a toggle in/out of a popup.
RPGACE.register('agentsIntoOracle', {

  init: function() {
    var self = this;
    self._relocate();
    RPGACE.registerBootTask(function() { return self._relocate(); });
  },

  _relocate: function() {
    if (document.getElementById('agents-in-oracle')) return; // already moved
    var agentsPage = document.getElementById('page-agents');
    var oraclePage = document.getElementById('page-advisor');
    if (!agentsPage || !oraclePage) return;

    var wrapper = document.createElement('div');
    wrapper.id = 'agents-in-oracle';
    wrapper.style.cssText = 'margin-top:24px;padding-top:20px;border-top:1px solid var(--border)';

    var heading = document.createElement('div');
    heading.className = 'section-title';
    heading.textContent = '⚡ Agent Actions';
    wrapper.appendChild(heading);

    // Move everything except the old page's own top title - Oracle's page
    // already has its own, no need for a second one.
    Array.prototype.slice.call(agentsPage.children).forEach(function(k) {
      if (k.classList && k.classList.contains('section-title') && k.textContent.indexOf('Composio Agent Control Centre') !== -1) return;
      wrapper.appendChild(k);
    });

    oraclePage.appendChild(wrapper);
  },

});
/* ===END:agentsIntoOracle=== */

/* ===MODULE:encyclopediaQoL=== */
// July 22 QoL request: "no real search, disconnected from taxonomy tree,
// no sense of what's actually been used." GODMODE evidence pass found:
// - Search: Encyclopedia only ever had category filter + sort-workflow
//   tabs (main.js setEncCategory/setEncSort) - no keyword search existed.
// - Taxonomy: encTaxonomyLink (this file) already tracks/shows link status
//   via entry.taxonomy_node_id - genuinely NOT disconnected - but the
//   status badge only ever appears in the EXPANDED per-entry view, so
//   Alex would have to open every card individually to see it. That's a
//   real visibility gap, not a missing feature.
// - Usage tracking ("what's actually been used"): confirmed via schema
//   check - the encyclopedia table has no applied/used column at all.
//   A real tracking mechanism needs a new column (a migration, Tier 3) -
//   deliberately NOT added here without Alex's explicit go; flagged in
//   patch_notes instead of guessed at.
//
// Search implementation: filters ALREADY-RENDERED cards by textContent
// match rather than re-deriving main.js's own filter/sort logic - avoids
// duplicating frozen-file behaviour, and re-applies after every
// re-render (wraps window.renderEncEntries, same established pattern as
// encTaxonomyLink just above) so it survives category/sort clicks.
RPGACE.register('encyclopediaQoL', {

  init: function() {
    var self = this;
    function patch() {
      if (typeof window.renderEncEntries !== 'function' || window._encQoLPatched) return;
      window._encQoLPatched = true;
      var orig = window.renderEncEntries;
      window.renderEncEntries = function() {
        var result = orig.apply(this, arguments);
        setTimeout(function() {
          self._injectTaxBadges();
          self._applySearch();
        }, 60);
        return result;
      };
    }
    patch();
    setTimeout(patch, 1500);
    setTimeout(function() { self._injectSearchBar(); }, 1500);
    RPGACE.hooks.on('page:show', function(name) {
      if (name === RPGACE.CONFIG.pages.encyclopedia) setTimeout(function() { self._injectSearchBar(); }, 300);
    });
  },

  _injectSearchBar: function() {
    if (document.getElementById('enc-search-input')) return;
    var countEl = document.getElementById('enc-count');
    var controlsRow = countEl ? countEl.parentElement : null;
    if (!controlsRow) return;
    var self = this;

    var input = document.createElement('input');
    input.type = 'text';
    input.id = 'enc-search-input';
    input.placeholder = '🔍 Search entries...';
    input.style.cssText = 'flex:1;min-width:160px;background:var(--panel2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:8px 12px;font-size:13px;font-family:Rajdhani,sans-serif;outline:none';
    input.addEventListener('input', function() { self._applySearch(); });
    controlsRow.insertBefore(input, countEl);
  },

  _applySearch: function() {
    var input = document.getElementById('enc-search-input');
    var term = input ? input.value.trim().toLowerCase() : '';
    var cards = document.querySelectorAll('#enc-output > div[id^="enc-card-"]');
    Array.prototype.forEach.call(cards, function(card) {
      var match = !term || card.textContent.toLowerCase().indexOf(term) !== -1;
      card.style.display = match ? '' : 'none';
    });
  },

  // Surfaces the SAME entry.taxonomy_node_id status encTaxonomyLink
  // already tracks, but in the always-visible header row instead of only
  // after expanding - the data-entry-id attribute is already present in
  // each card's expanded section (just visually hidden, not absent from
  // the DOM), so this reads it directly rather than recomputing anything.
  _injectTaxBadges: function() {
    var cards = document.querySelectorAll('#enc-output > div[id^="enc-card-"]');
    Array.prototype.forEach.call(cards, function(card) {
      if (card.dataset.taxBadge) return;
      card.dataset.taxBadge = '1';
      var idHolder = card.querySelector('[data-entry-id]');
      var id = idHolder ? idHolder.getAttribute('data-entry-id') : null;
      var entry = (window.ENC_ALL_ENTRIES || []).find(function(e) { return String(e.id || e.created_at) === String(id); });
      // Header row is the div with the toggleEncEntry onclick; its first
      // child wraps [title div, meta div] - meta is that wrapper's last
      // child. Explicit structural knowledge from the real markup, not a
      // generic nth-child guess that could match the wrong nested div.
      var headerRow = card.querySelector('[onclick^="toggleEncEntry"]');
      var metaRow = headerRow && headerRow.firstElementChild && headerRow.firstElementChild.lastElementChild;
      if (!entry || !metaRow) return;
      var badge = document.createElement('span');
      if (entry.taxonomy_node_id) {
        badge.textContent = ' · 🌳 Linked';
        badge.style.color = '#4CAF82';
      } else {
        badge.textContent = ' · ○ Not yet placed';
        badge.style.color = 'rgba(226,226,236,0.35)';
      }
      metaRow.appendChild(badge);
    });
  },

});
/* ===END:encyclopediaQoL=== */

/* ===MODULE:journalQoL=== */
// July 22 QoL request: "no search or filtering, doesn't surface the new
// audit trails, no tagging/categorisation." GODMODE evidence pass: the
// journal table's real column is `source` (schedule/feynman/oracle/
// beatLog/contentProductionLive/morning-routine/manual, confirmed by
// direct query) - already an implicit category, just never surfaced as
// filterable tags in the UI. No stable per-card id/class exists in
// refreshJournalDisplay's render (main.js, frozen) - unlike Encyclopedia,
// which tags each card with enc-card-${safeId} - so search/filter here
// works purely by textContent match over #journal-output's direct
// children rather than an id-based lookup; simpler, and doesn't require
// touching or duplicating the frozen render function.
RPGACE.register('journalQoL', {

  SOURCES: ['schedule', 'feynman', 'oracle', 'beatLog', 'contentProductionLive', 'morning-routine', 'manual'],

  init: function() {
    var self = this;
    function patch() {
      if (typeof window.refreshJournalDisplay !== 'function' || window._journalQoLPatched) return;
      window._journalQoLPatched = true;
      var orig = window.refreshJournalDisplay;
      window.refreshJournalDisplay = function() {
        var result = orig.apply(this, arguments);
        Promise.resolve(result).then(function() {
          setTimeout(function() {
            self._injectAuditEntries();
            self._applyFilter();
          }, 80);
        });
        return result;
      };
    }
    patch();
    setTimeout(patch, 1500);
    setTimeout(function() { self._injectControls(); }, 1500);
    RPGACE.hooks.on('page:show', function(name) {
      if (name === RPGACE.CONFIG.pages.journal) setTimeout(function() { self._injectControls(); }, 300);
    });
  },

  _injectControls: function() {
    if (document.getElementById('journal-search-input')) return;
    var countEl = document.getElementById('journal-count');
    var controlsRow = countEl ? countEl.parentElement : null;
    if (!controlsRow) return;
    var self = this;

    var input = document.createElement('input');
    input.type = 'text';
    input.id = 'journal-search-input';
    input.placeholder = '🔍 Search journal...';
    input.style.cssText = 'flex:1;min-width:160px;background:var(--panel2);border:1px solid var(--border);border-radius:6px;color:var(--text);padding:8px 12px;font-size:13px;font-family:Rajdhani,sans-serif;outline:none';
    input.addEventListener('input', function() { self._applyFilter(); });
    controlsRow.insertBefore(input, countEl);

    var chipRow = document.createElement('div');
    chipRow.id = 'journal-source-chips';
    chipRow.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px';
    var allChip = self._makeChip('all', 'All');
    chipRow.appendChild(allChip);
    self.SOURCES.forEach(function(s) { chipRow.appendChild(self._makeChip(s, s)); });
    controlsRow.insertAdjacentElement('afterend', chipRow);
    self._activeSource = 'all';
  },

  _makeChip: function(key, label) {
    var self = this;
    var btn = document.createElement('button');
    btn.dataset.sourceKey = key;
    btn.textContent = label;
    btn.style.cssText = 'padding:5px 12px;border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;font-family:Rajdhani,sans-serif;border:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.03);color:rgba(226,226,236,0.5)';
    btn.onclick = function() {
      self._activeSource = key;
      Array.prototype.forEach.call(document.querySelectorAll('#journal-source-chips button'), function(b) {
        var on = b.dataset.sourceKey === key;
        b.style.background = on ? 'rgba(201,168,76,0.15)' : 'rgba(255,255,255,0.03)';
        b.style.borderColor = on ? 'rgba(201,168,76,0.45)' : 'rgba(255,255,255,0.1)';
        b.style.color = on ? 'var(--gold)' : 'rgba(226,226,236,0.5)';
      });
      self._applyFilter();
    };
    return btn;
  },

  _applyFilter: function() {
    var input = document.getElementById('journal-search-input');
    var term = input ? input.value.trim().toLowerCase() : '';
    var source = this._activeSource || 'all';
    var cards = document.querySelectorAll('#journal-output > div');
    Array.prototype.forEach.call(cards, function(card) {
      var text = card.textContent.toLowerCase();
      var matchesTerm = !term || text.indexOf(term) !== -1;
      var matchesSource = source === 'all' || text.indexOf(source.toLowerCase()) !== -1;
      card.style.display = (matchesTerm && matchesSource) ? '' : 'none';
    });
  },

  // Surfaces taxonomy_decision_log + oracle_dev_suggestions (both built
  // earlier this session) as readable, clearly-tagged, READ-ONLY entries
  // in the Journal feed - this is exactly the "running log" page these
  // two append-only tables were missing a human-readable home in.
  // Fetched fresh each render (both tables are tiny; no caching concern),
  // prepended above the real journal entries, visually distinguished so
  // they're never confused with something Alex wrote or can delete.
  _injectAuditEntries: function() {
    var el = document.getElementById('journal-output');
    if (!el || el.querySelector('.journal-audit-entry')) return;
    if (el.textContent.indexOf('Your Journal is Empty') !== -1) return;

    var self = this;
    Promise.all([
      RPGACE.sb.select('taxonomy_decision_log', 'order=created_at.desc&limit=10').catch(function() { return []; }),
      RPGACE.sb.select('oracle_dev_suggestions', 'order=created_at.desc&limit=10').catch(function() { return []; }),
    ]).then(function(results) {
      var decisions = results[0] || [];
      var suggestions = results[1] || [];
      var rows = decisions.map(function(d) {
        return { date: (d.created_at || '').slice(0, 10), label: '🧬 Taxonomy Decision', color: '#4CAF82', text: 'Placed at ' + (d.path || '') + (d.insight_text ? ': ' + d.insight_text.slice(0, 140) : '') };
      }).concat(suggestions.map(function(s) {
        return { date: (s.created_at || '').slice(0, 10), label: '🧪 Oracle Suggestion', color: '#4A8CCC', text: (s.suggestion_text || '').slice(0, 200), status: s.status };
      }));
      if (!rows.length) return;
      rows.sort(function(a, b) { return (b.date || '').localeCompare(a.date || ''); });
      var html = rows.map(function(r) {
        return '<div class="journal-audit-entry" style="background:var(--panel2);border:1px solid var(--border);border-left:3px solid ' + r.color + ';border-radius:10px;padding:14px 16px;margin-bottom:12px;opacity:0.9">'
          + '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;flex-wrap:wrap">'
          + '<div style="font-family:Cinzel,serif;font-size:12px;color:' + r.color + ';font-weight:600">' + r.label + (r.status ? ' — ' + r.status : '') + '</div>'
          + '<div style="font-size:11px;color:var(--muted)">📅 ' + (r.date || '') + '</div>'
          + '</div>'
          + '<div style="font-size:12px;color:var(--text);line-height:1.6;margin-top:6px">' + r.text.replace(/</g, '&lt;') + '</div>'
          + '</div>';
      }).join('');
      el.insertAdjacentHTML('afterbegin', html);
      self._applyFilter();
    });
  },

});
/* ===END:journalQoL=== */

/* ===END_DOMAIN:SCHEDULE=== */

/* ===MODULE:pwaInstall=== */
// July 22: makes RPGACE a real installable PWA (Android/desktop "Add to
// Home Screen"/"Install app"). Registration has zero dependency on
// RPGACE.CONFIG or login state, so it runs immediately at parse time
// rather than waiting behind the rpgace:ready gate - the earlier a
// browser sees a valid SW + manifest, the sooner it offers the install
// prompt. Belongs in rpgace_core.js (not a new <script> tag - see the
// "never add a static script tag" landmine) since it's plain JS logic,
// not an external library needing its own file.
RPGACE.register('pwaInstall', {
  init: function() {
    // No-op: registration already ran below, outside init(). This module
    // exists mainly so failures show up in RPGACE's normal module-init
    // logging/console conventions rather than as a silent bare call.
  },
  _register: function() {
    if (!('serviceWorker' in navigator)) return;
    navigator.serviceWorker.register('/sw.js').then(function(reg) {
      console.log('[RPGACE] Service worker registered', reg.scope);
    }).catch(function(err) {
      console.warn('[RPGACE] Service worker registration failed', err.message);
    });
  }
});
RPGACE.modules.pwaInstall._register();
/* ===END:pwaInstall=== */

/* ===MODULE:authGate=== */
// July 23 — Tier 3 security fix, Alex-authorized ("do now"). Real problem
// (confirmed by the /5thDimension Phase 1 audit): CORRECT_PW lived as a
// plain string in main.js, shipped to every browser and trivially
// readable via view-source; separately, every /api/*.js endpoint had
// ZERO server-side auth - anyone who found the URL could invoke Oracle/
// Composio actions directly, bypassing the password screen entirely.
// Both are fixed by the SAME mechanism: the real password check now
// happens server-side (api/auth.js, comparing against process.env.
// CORRECT_PW - never shipped to the client), and on success the server
// hands back a shared secret (process.env.RPGACE_API_SECRET) that gets
// attached to every subsequent /api/* call via the single fetch() wrap
// below - not 26 separate call-site edits (main.js's own 15 + this
// file's 11), one real choke point, matching Alex's own "same steps
// must go through one pipeline" rule from this same session.
// main.js's checkPassword() (FROZEN, one deliberate logged exception,
// see patch_notes.html) now calls window.RPGACE_verifyPassword(pw)
// instead of comparing a local constant - CORRECT_PW itself is removed
// from main.js entirely, so the real value is never shipped to a browser.
// Runs immediately at parse time (like pwaInstall just above), not
// gated behind rpgace:ready - it needs to exist before any human could
// plausibly type a password and hit Enter.
RPGACE.register('authGate', {
  init: function() {
    // No-op: setup runs immediately below, outside init() - same
    // reasoning as pwaInstall's own no-op init().
  },

  _apiSecret: null,

  // Called by main.js's wrapped checkPassword(). Returns a real
  // true/false the wrap can act on, unlike the old synchronous
  // client-side compare this replaces.
  verify: function(pw) {
    var self = this;
    return fetch('/api/auth', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ password: pw })
    }).then(function(res) {
      return res.json().then(function(data) { return { ok: res.ok, data: data }; });
    }).then(function(r) {
      if (r.ok && r.data && r.data.ok && r.data.secret) {
        self._apiSecret = r.data.secret;
        return true;
      }
      return false;
    }).catch(function(e) {
      console.warn('[RPGACE authGate] verify failed', e.message);
      return false;
    });
  },

  // Global fetch() wrap: attaches the shared secret to every /api/*
  // request except /api/auth itself (which doesn't have the secret yet -
  // that's the whole point of it). Installed once, immediately, so it
  // covers every one of the ~26 real call sites across main.js and this
  // file without touching any of them individually - real deduplication
  // (one shared pipeline instead of many hand-rolled copies), not just a
  // security fix.
  _installFetchWrap: function() {
    var self = this;
    if (window._authGateFetchPatched) return;
    window._authGateFetchPatched = true;
    var origFetch = window.fetch.bind(window);
    window.fetch = function(input, init) {
      try {
        var url = typeof input === 'string' ? input : (input && input.url);
        if (url && url.indexOf('/api/') === 0 && url !== '/api/auth' && self._apiSecret) {
          init = init || {};
          if (init.headers instanceof Headers) {
            init.headers.set('X-RPGACE-Auth', self._apiSecret);
          } else {
            init.headers = Object.assign({}, init.headers || {}, { 'X-RPGACE-Auth': self._apiSecret });
          }
        }
      } catch (e) { /* never let the wrap itself break a real request */ }
      return origFetch(input, init);
    };
  }
});
RPGACE.modules.authGate._installFetchWrap();
window.RPGACE_verifyPassword = function(pw) { return RPGACE.modules.authGate.verify(pw); };
/* ===END:authGate=== */

/* ===MODULE:careerStatCard=== */
// July 22 GODMODE finding: the profile card's HP/MP bars are 100% inert
// (hardcoded widths, never touched by any function anywhere in main.js or
// this file - confirmed by grep, not assumed) and "Streak" is a hardcoded
// literal "1", also never updated. XP/Level/"Done" DO have real code
// (STATE.xp/totalXP/tasksCompleted, addXP(), levelUp() in main.js) but
// STATE lives only in memory with zero persistence anywhere (no
// localStorage, no Supabase write) - it silently resets to zero on every
// single page load. Meanwhile real, persisted evidence of career-path
// progress already sits unused in Supabase: content_productions (the
// actual governing-rule metric - beats/videos actually shipped),
// journal, encyclopedia_insights, taxonomy_proposals, bookworm_chapters,
// reference_tracks. This module replaces the inert/ephemeral numbers with
// a real, honestly-computed career score derived from that real data,
// re-rendered on every load - nothing here is faked to look better than
// it is. Confirmed via direct Supabase query (not guessed) that
// content_productions currently has 0 rows actually posted to a real
// platform - the Output lane will genuinely read 0 until that changes.
// That is deliberate, not a bug: inflating it would just be a shinier
// version of the exact problem being fixed.
//
// Council of 5 "why not to build this" considered and addressed:
// - Goodhart's-law risk (gaming the tree for XP instead of shipping real
//   content) is why Output (real shipped content) and Growth (learning/
//   knowledge-tree activity) are kept as SEPARATE lanes, not one blended
//   number - Alex can see at a glance whether he's actually shipping or
//   just building/studying, matching CLAUDE.md's own governing-rule
//   structure (shipping is primary; RPGACE-building is a named exception)
//   instead of smoothing the two together into one misleading composite.
// - Considered and explicitly rejected: variable-ratio/randomised reward
//   schedules (the mobile-game "loot box" pattern) - genuinely effective
//   at driving compulsive engagement, but that's an anti-pattern for a
//   personal productivity tool whose own governing rule is about real
//   output, not engagement-farming. Not built, on purpose.
// - bookworm_chapters is counted toward the cumulative Growth total but
//   deliberately EXCLUDED from the streak calculation and the recent-wins
//   feed: confirmed via direct query that all of a book's chapter rows
//   share one bulk-insert created_at timestamp from TOC detection, not
//   the real per-chapter analysis time - using it for "recent activity"
//   would show a misleading date.
// - LEVEL_TITLES/xp bands are a deliberate LOCAL copy of main.js's real
//   ones, not a live cross-script reference - main.js is frozen and its
//   top-level consts aren't meant to be reached into from here; a small
//   duplicated array is more robust and easier for a future session to
//   follow than relying on classic-script global-scope leakage.
RPGACE.register('careerStatCard', {
  WEIGHTS: {
    contentShipped: 100,
    contentIdea: 5,
    journalEntry: 8,
    insight: 4,
    proposalAccepted: 6,
    chapterComplete: 15,
    referenceTrack: 3
  },
  LEVEL_TITLES: ['Novice Producer','Content Apprentice','Rising Creator','Consistent Grinder','Viral Contender','Established Creator','Platform Veteran','The Producer','Elite Creator'],
  // Cumulative XP ceiling per level - running total of main.js's own
  // per-level requirements ([500,1200,2200,3500,5000,7000,9500,12500]),
  // reused so a "Level" here means the same thing on the same scale.
  CUM_BANDS: [500,1700,3900,7400,12400,19400,28900,41400],

  init: function() {
    var self = this;
    self._render();
    RPGACE.registerBootTask(function() { return self._render(); });
    RPGACE.hooks.on('xp:awarded', function() { self._render(); });
    RPGACE.hooks.on('page:show', function() { self._render(); });
  },

  // July 23 — real bug found while investigating a reported 10-20s post-
  // login freeze (worse on mobile: couldn't scroll at all; on desktop,
  // nav/cards wouldn't click but the page could still scroll). Traced the
  // real call pattern: init() calls _fetchAll() immediately, again at
  // 1500ms, and again on every single page:show - plus the new July 23
  // boot-loader prefetch calls it once more before login even completes.
  // Multiple waves of 8 Supabase calls each, fired close enough together
  // that NONE of them can benefit from RPGACE.cache yet (a cache entry
  // only exists once a call actually resolves) - up to 32 near-simultaneous
  // requests to the same origin. Browsers cap concurrent connections per
  // origin (~6 in Chrome), so the later calls queue behind the earlier
  // ones - on a slower/higher-latency mobile connection this queueing
  // alone could plausibly stretch into many real seconds. Deduplicating
  // concurrent calls to share one real in-flight request fixes this
  // directly, regardless of whether it's the whole story.
  _inflightFetch: null,
  _fetchAll: function() {
    if (this._inflightFetch) return this._inflightFetch;
    var self = this;
    var sb = RPGACE.sb;
    var safe = function(p) { return p.catch(function() { return []; }); };
    this._inflightFetch = Promise.all([
      safe(sb.select('content_productions', 'select=con_id,status,youtube_url,instagram_url,tiktok_url,title,idea,notes,created_at&order=created_at.desc&limit=200')),
      safe(sb.select('journal', 'select=title,content,source,created_at&order=created_at.desc&limit=200')),
      safe(sb.select('encyclopedia_insights', 'select=source_entry_title,insight_text,macro_category,micro_categories,created_at&order=created_at.desc&limit=200')),
      safe(sb.select('taxonomy_proposals', 'select=proposed_path,proposed_steps,phylum_number,source_type,source_id,reviewed_at,created_at&status=eq.accepted&order=created_at.desc&limit=200')),
      safe(sb.select('bookworm_chapters', 'select=chapter_title,status,created_at&status=eq.complete&order=created_at.desc&limit=200')),
      safe(sb.select('reference_tracks', 'select=title,artist,bpm,key,scale,energy,mood,genre,notes,analysed,created_at&order=created_at.desc&limit=200')),
      // Chronicles finance ledger (July 22, chronicles_spec_backlog.txt) -
      // deliberately NOT folded into the totalXP/growthTotal weights below.
      // Confirmed via interrogation: this is a separate visibility lane,
      // not part of the career-score formula.
      safe(sb.select('chronicles_finance', 'select=*&order=entry_date.desc,created_at.desc&limit=500')),
      // Claude Code / RPGACE system updates (July 22) - every real dev-session
      // change to RPGACE now gets a row here too, so Chronicles is a single
      // real timeline of BOTH Alex's own actions AND what Claude Code shipped
      // on the app, per Alex's explicit "make these updates known in
      // chronicles from now on." See CLAUDE.md's "Chronicles system-update
      // logging" rule for the standing convention future sessions follow.
      safe(sb.select('system_updates', 'select=*&order=created_at.desc&limit=200'))
    ]).then(function(results) {
      return {
        content: Array.isArray(results[0]) ? results[0] : [],
        journal: Array.isArray(results[1]) ? results[1] : [],
        insights: Array.isArray(results[2]) ? results[2] : [],
        proposals: Array.isArray(results[3]) ? results[3] : [],
        chapters: Array.isArray(results[4]) ? results[4] : [],
        tracks: Array.isArray(results[5]) ? results[5] : [],
        finance: Array.isArray(results[6]) ? results[6] : [],
        systemUpdates: Array.isArray(results[7]) ? results[7] : []
      };
    });
    // Clear the in-flight lock once settled (success or failure) so a
    // later real refresh (cache expired, 60s+ later) can fetch again -
    // this dedup is only meant to collapse calls that land in the same
    // narrow window, not permanently share one stale result.
    this._inflightFetch.then(function() { self._inflightFetch = null; }, function() { self._inflightFetch = null; });
    return this._inflightFetch;
  },

  _isShipped: function(row) {
    return !!(row.youtube_url || row.instagram_url || row.tiktok_url || (row.status && /posted/i.test(row.status)));
  },

  _dateStr: function(iso) { return iso ? iso.slice(0, 10) : null; },

  _computeStreak: function(data) {
    var days = {};
    var addAll = function(rows) { rows.forEach(function(r) { var d = data.self._dateStr(r.created_at); if (d) days[d] = true; }); };
    addAll(data.content); addAll(data.journal); addAll(data.insights); addAll(data.proposals); addAll(data.tracks);
    var today = new Date();
    var toKey = function(d) { return d.toISOString().slice(0, 10); };
    var todayKey = toKey(today);
    var yest = new Date(today.getTime() - 86400000);
    var yestKey = toKey(yest);
    if (!days[todayKey] && !days[yestKey]) return 0;
    var cursor = days[todayKey] ? today : yest;
    var count = 0;
    while (days[toKey(cursor)]) {
      count++;
      cursor = new Date(cursor.getTime() - 86400000);
    }
    return count;
  },

  _relTime: function(iso) {
    var diff = Date.now() - new Date(iso).getTime();
    var mins = Math.floor(diff / 60000);
    if (mins < 1) return 'just now';
    if (mins < 60) return mins + 'm ago';
    var hrs = Math.floor(mins / 60);
    if (hrs < 24) return hrs + 'h ago';
    return Math.floor(hrs / 24) + 'd ago';
  },

  _levelFor: function(totalXP) {
    var bands = this.CUM_BANDS;
    for (var i = 0; i < bands.length; i++) {
      if (totalXP < bands[i]) {
        var floor = i === 0 ? 0 : bands[i - 1];
        return { levelNum: i + 1, title: this.LEVEL_TITLES[i], floor: floor, ceil: bands[i] };
      }
    }
    var last = bands.length - 1;
    return { levelNum: bands.length + 1, title: this.LEVEL_TITLES[this.LEVEL_TITLES.length - 1], floor: bands[last], ceil: bands[last] + 10000 };
  },

  _render: function() {
    var self = this;
    self._fetchAll().then(function(data) {
      data.self = self; // let _computeStreak reuse _dateStr without rebinding
      var W = self.WEIGHTS;
      var shipped = data.content.filter(function(r) { return self._isShipped(r); });
      var ideas = data.content.filter(function(r) { return !self._isShipped(r); });

      var totalXP = shipped.length * W.contentShipped
        + ideas.length * W.contentIdea
        + data.journal.length * W.journalEntry
        + data.insights.length * W.insight
        + data.proposals.length * W.proposalAccepted
        + data.chapters.length * W.chapterComplete
        + data.tracks.length * W.referenceTrack;

      var lvl = self._levelFor(totalXP);
      var streak = self._computeStreak(data);
      var totalActions = shipped.length + ideas.length + data.journal.length + data.insights.length + data.proposals.length + data.chapters.length + data.tracks.length;
      var growthTotal = data.journal.length + data.insights.length + data.proposals.length + data.chapters.length + data.tracks.length;

      // Output lane: real shipped count only - the honest, ungamed number.
      var outMilestone = Math.max(3, Math.ceil((shipped.length + 1) / 3) * 3);
      var outBar = document.getElementById('output-bar'), outVal = document.getElementById('output-val');
      if (outBar) outBar.style.transform = 'scaleX(' + (Math.min(100, Math.round(shipped.length / outMilestone * 100)) / 100) + ')';
      if (outVal) outVal.textContent = shipped.length + ' / ' + outMilestone + ' shipped';

      // Growth lane: combined small-wins volume.
      var groMilestone = Math.max(50, Math.ceil((growthTotal + 1) / 50) * 50);
      var groBar = document.getElementById('growth-bar'), groVal = document.getElementById('growth-val');
      if (groBar) groBar.style.transform = 'scaleX(' + (Math.min(100, Math.round(growthTotal / groMilestone * 100)) / 100) + ')';
      if (groVal) groVal.textContent = growthTotal + ' / ' + groMilestone;

      // XP lane: real cumulative career score, progress within current level.
      var xpBar = document.getElementById('xp-bar'), xpVal = document.getElementById('xp-val');
      var bandWidth = lvl.ceil - lvl.floor;
      var withinLevel = totalXP - lvl.floor;
      if (xpBar) xpBar.style.transform = 'scaleX(' + (Math.min(100, Math.round(withinLevel / bandWidth * 100)) / 100) + ')';
      if (xpVal) xpVal.textContent = withinLevel + ' / ' + bandWidth;

      var charTitle = document.getElementById('char-title');
      if (charTitle) charTitle.innerHTML = lvl.title + ' • Level <span id="lvl-display">' + lvl.levelNum + '</span>';

      var statTasks = document.getElementById('stat-tasks'); if (statTasks) statTasks.textContent = totalActions;
      var statStreak = document.getElementById('stat-streak'); if (statStreak) statStreak.textContent = streak;
      var statLvl = document.getElementById('stat-lvl'); if (statLvl) statLvl.textContent = lvl.levelNum;
      var statXp = document.getElementById('stat-xp'); if (statXp) statXp.textContent = totalXP;
      // July 23: the standalone "Recent Wins" header+feed that used to sit
      // here (._renderWins/._ensureWinsContainer) is gone - real feedback
      // from Alex, this was a bespoke treatment that didn't match the
      // other 11 dashDeck cards visually. Chronicles now lives ONLY as a
      // real card in that grid (dashDeck.MODULES 'chronicles' entry ->
      // chroniclesLog._openCard()), reusing this exact _buildItems/
      // _showDetail logic for its popup preview - removed, not duplicated.
    }).catch(function(e) {
      console.warn('[RPGACE:careerStatCard] render failed, leaving prior display untouched', e.message);
    });
  },

  // July 22, round 3: renamed "Recent Wins" -> "The Chronicles" (Alex's own
  // name for the whole group), and added a real "View Full Log" nav button
  // - the group's real expand point, opening the new dedicated
  // #page-chronicles page (chroniclesLog module) rather than growing this
  // dashboard preview indefinitely. See chronicles_spec_backlog.txt.
  // July 22, round 2: Alex's real complaint was the taxonomy rows in this
  // feed all read as the same generic "Taxonomy insight placed" line with
  // nothing to click into. taxonomy_proposals actually stores rich real
  // content per row (proposed_path, proposed_steps.insightText/synthesis/
  // justification/confidenceScore, source_type/source_id) - it was just
  // never being read. Each feed row is now a real DOM node (not an innerHTML
  // string) carrying its full source row, clickable into a detail popup
  // built from RPGACE.modules.dashDeck._popup (the one shared overlay
  // helper that already exists in this file - reused rather than hand-
  // rolling a second one, per the standing "grep before new UI behaviour,
  // this project has a history of duplicate implementations" rule).
  // Shared by the Chronicles dashboard-card popup (chroniclesLog._openCard,
  // top 5) and the full Chronicles log page (chroniclesLog, all of them) -
  // one place builds the item list so both surfaces can never drift out of sync.
  _buildItems: function(data, shipped, ideas) {
    var self = this;
    var items = [];
    shipped.forEach(function(r) { items.push({ t: r.created_at, icon: '🚀', label: 'Shipped: ' + (r.title || 'content'), type: 'content_shipped', row: r }); });
    ideas.forEach(function(r) { items.push({ t: r.created_at, icon: '💡', label: 'Idea logged: ' + (r.title || 'content'), type: 'content_idea', row: r }); });
    data.journal.forEach(function(r) { items.push({ t: r.created_at, icon: '📓', label: 'Journal: ' + (r.title || 'entry'), type: 'journal', row: r }); });
    data.insights.forEach(function(r) { items.push({ t: r.created_at, icon: '🧠', label: 'Insight: ' + (r.source_entry_title || 'captured'), type: 'insight', row: r }); });
    data.proposals.forEach(function(r) { items.push({ t: r.created_at, icon: '🌳', label: 'Taxonomy: ' + self._proposalShortName(r), type: 'proposal', row: r }); });
    data.tracks.forEach(function(r) { items.push({ t: r.created_at, icon: '🎧', label: 'Reference logged: ' + (r.title || 'track'), type: 'track', row: r }); });
    (data.finance || []).forEach(function(r) {
      var isSale = r.type === 'sale';
      items.push({ t: r.created_at, icon: isSale ? '💰' : '🧾', label: (isSale ? 'Sale: ' : 'Expense: ') + (r.item || r.category) + ' (£' + r.amount + ')', type: isSale ? 'finance_sale' : 'finance_expense', row: r });
    });
    (data.systemUpdates || []).forEach(function(r) {
      items.push({ t: r.created_at, icon: '🛠️', label: 'Claude Code: ' + (r.title || 'system update'), type: 'system_update', row: r });
    });
    items.sort(function(a, b) { return new Date(b.t) - new Date(a.t); });
    return items;
  },

  // proposed_steps' shape varies by engine (phylum_path / concept_fusion /
  // plain path-array) - this pulls a short human name out of whichever
  // shape is actually present, for the feed row label.
  _proposalShortName: function(r) {
    function truncate(s, n) { return s.length > n ? s.slice(0, n - 1) + '…' : s; }
    var ps = (r && r.proposed_steps) || {};
    if (ps.insightText) return truncate(ps.insightText, 60);
    if (ps.newName) return truncate(ps.newName, 60);
    if (r && r.proposed_path) { var segs = r.proposed_path.split(/→|\//); return truncate(segs[segs.length - 1].trim(), 60); }
    return 'new branch added';
  },

  _esc: function(s) { return RPGACE.utils.escapeHtml(s); },

  // Builds the {what, outcome, whereStored, whySignificant} shape every
  // detail popup renders, from whichever real row type was clicked.
  _detailFor: function(it) {
    var self = this, r = it.row, esc = function(s) { return self._esc(s); };
    if (it.type === 'proposal') {
      var ps = r.proposed_steps || {};
      var what = ps.insightText || ps.newName || (ps.explainers && ps.explainers[0]) || 'New taxonomy branch added';
      var whySig = ps.justification || ps.synthesis || (ps.explainers && ps.explainers.join(' ')) || null;
      if (ps.confidenceScore) whySig = (whySig ? whySig + ' ' : '') + '(confidence ' + ps.confidenceScore + '/10)';
      var sourceLine = 'Auto-detected during real Phylum Path work';
      if (r.source_type === 'content_intelligence' && r.source_id && /^https?:\/\//.test(r.source_id)) {
        sourceLine = 'Sourced from: <a href="' + esc(r.source_id) + '" target="_blank" rel="noopener" style="color:var(--gold)">' + esc(r.source_id) + '</a>';
      } else if (r.source_type === 'phylum_path_concept_fusion') {
        sourceLine = 'Synthesised by merging two existing tree branches (Concept Fusion)';
      }
      return {
        eyebrow: '🌳 Phylum ' + (r.phylum_number != null ? r.phylum_number : '?') + ' • Taxonomy Tree',
        title: 'Taxonomy insight accepted',
        rows: [
          ['What was done', esc(what)],
          ['Outcome', 'Accepted into the tree' + (r.reviewed_at ? ' on ' + r.reviewed_at.slice(0, 10) : '')],
          ['Where stored', esc(r.proposed_path || '—')],
          ['Why significant', whySig ? esc(whySig) : 'Fills a real gap identified in your knowledge tree.'],
          ['Source', sourceLine]
        ]
      };
    }
    if (it.type === 'journal') {
      return {
        eyebrow: '📓 Journal', title: r.title || 'Journal entry',
        rows: [
          ['What was done', esc(r.content || '—')],
          ['Outcome', 'Logged to your Journal'],
          ['Where stored', 'journal table'],
          ['Why significant', 'Source: ' + esc(r.source || 'manual')]
        ]
      };
    }
    if (it.type === 'insight') {
      return {
        eyebrow: '🧠 Encyclopedia', title: 'Insight captured',
        rows: [
          ['What was done', esc(r.insight_text || '—')],
          ['Outcome', 'Captured under ' + esc(r.macro_category || 'general')],
          ['Where stored', 'Encyclopedia • source: ' + esc(r.source_entry_title || '—')],
          ['Why significant', (r.micro_categories && r.micro_categories.length) ? 'Tags: ' + esc(r.micro_categories.join(', ')) : 'A real, reviewed piece of learning added to your library.']
        ]
      };
    }
    if (it.type === 'content_shipped' || it.type === 'content_idea') {
      var shipped = it.type === 'content_shipped';
      return {
        eyebrow: shipped ? '🚀 Content — Shipped' : '💡 Content — Idea', title: r.title || 'Content production',
        rows: [
          ['What was done', esc(r.idea || r.title || '—')],
          ['Outcome', shipped ? 'Posted to a real platform' : 'Logged to the content pipeline, not yet posted'],
          ['Where stored', 'content_productions #' + (r.con_id != null ? r.con_id : '?')],
          ['Why significant', shipped ? 'This is the governing-rule metric — a real beat/video that reached an audience.' : (r.notes ? esc(r.notes) : 'A real step toward shipping — turn this into a posted piece to move the Output lane.')]
        ]
      };
    }
    if (it.type === 'track') {
      return {
        eyebrow: '🎧 Reference Library', title: (r.artist ? r.artist + ' — ' : '') + (r.title || 'track'),
        rows: [
          ['What was done', 'Logged as a reference track' + (r.analysed ? ' and analysed' : '')],
          ['Outcome', [r.bpm ? r.bpm + ' BPM' : null, r.key ? r.key + ' ' + (r.scale || '') : null].filter(Boolean).join(' • ') || '—'],
          ['Where stored', 'reference_tracks table'],
          ['Why significant', [r.mood, r.genre].filter(Boolean).join(' • ') || (r.notes ? esc(r.notes) : 'Builds your real reference library for future productions.')]
        ]
      };
    }
    if (it.type === 'finance_sale' || it.type === 'finance_expense') {
      var isSale = it.type === 'finance_sale';
      return {
        eyebrow: isSale ? '💰 Chronicles — Sale' : '🧾 Chronicles — Expense',
        title: esc(r.item || r.category || 'Entry'),
        rows: [
          ['What was done', esc(r.item || r.category) + ' — £' + r.amount],
          ['Outcome', (isSale ? 'Real income logged' : 'Real spend logged') + (r.category ? ' under "' + esc(r.category) + '"' : '')],
          ['Where stored', 'chronicles_finance table • ' + esc(r.entry_date || '')],
          ['Why significant', isSale
            ? 'Real revenue toward your music career. Kept as its own visibility lane, deliberately separate from the Output score above — a sale and a shipped video are different real wins.'
            : (r.notes ? esc(r.notes) : 'Tracked for your own visibility — keep the real receipt for actual tax filing; this is not a substitute for bookkeeping.')]
        ]
      };
    }
    if (it.type === 'system_update') {
      return {
        eyebrow: '🛠️ Claude Code — RPGACE System Update',
        title: esc(r.title || 'System update'),
        rows: [
          ['What was done', esc(r.summary || r.title || '—')],
          ['Outcome', 'Shipped to main by a Claude Code dev session'],
          ['Where stored', 'system_updates table • category: ' + esc(r.category || 'feature')],
          ['Why significant', 'Real infrastructure/behaviour change to RPGACE itself, logged here so app-side activity and dev-side activity share one real timeline.']
        ]
      };
    }
    return { eyebrow: it.icon + ' Activity', title: it.label, rows: [['What was done', esc(it.label)], ['Outcome', '—'], ['Where stored', '—'], ['Why significant', '—']] };
  },

  _showDetail: function(it) {
    var dd = RPGACE.modules.dashDeck;
    if (!dd || !dd._popup) { console.warn('[RPGACE:careerStatCard] dashDeck._popup unavailable'); return; }
    var d = this._detailFor(it);
    var pop = dd._popup({ eyebrow: d.eyebrow, title: d.title, width: '560px', accent: 'var(--gold)' });
    pop.box.innerHTML = d.rows.map(function(row) {
      return '<div style="margin-bottom:12px"><div style="font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-bottom:3px">' + row[0] + '</div>'
        + '<div style="font-size:13px;color:var(--text);line-height:1.5">' + row[1] + '</div></div>';
    }).join('');
  }
});
/* ===END:careerStatCard=== */

/* ===MODULE:chroniclesLog=== */
// July 22, round 3 — Alex: "call this whole group the chronicles, that can
// have an expand button that shows logs of what's done, this can then be
// tied to future accounting and logistics metrics for drum kit and beat
// sales, spending on equipment for tax write off etc." Interrogated first
// (real answers recorded verbatim in chronicles_spec_backlog.txt) rather
// than guessing at scope, since this touches real financial record-keeping:
// full log page (not just a bigger inline list), a personal-visibility-only
// finance tracker (not bookkeeping-grade), a SEPARATE finance ledger table
// (chronicles_finance - not inside Phylum 17 Negotium, which stays reserved
// for conceptual business/tax knowledge and is deliberately untouched here),
// manual entry only (no BeatStars/bank integration in this pass).
//
// Page injected at runtime (same proven pattern as phylumPath._injectPageShell
// - main.js's showPage() only needs an element with a matching #page-<name>
// id and class="page" to exist by click time, it doesn't care when or how
// it was created). No main.js edit.
RPGACE.register('chroniclesLog', {
  FILTERS: ['all', 'proposal', 'journal', 'insight', 'content_shipped', 'content_idea', 'track', 'finance_sale', 'finance_expense', 'system_update'],
  FILTER_LABELS: { all: 'All', proposal: '🌳 Taxonomy', journal: '📓 Journal', insight: '🧠 Insight', content_shipped: '🚀 Shipped', content_idea: '💡 Ideas', track: '🎧 Reference', finance_sale: '💰 Sales', finance_expense: '🧾 Expenses', system_update: '🛠️ System' },
  CATEGORY_SUGGESTIONS: ['Equipment', 'Software & Plugins', 'Drum Kits & Samples', 'Studio & Rent', 'Marketing', 'Beat Sale', 'Sample Pack Sale', 'Mixing/Mastering Service', 'Travel', 'Other'],

  init: function() {
    var self = this;
    self._activeFilter = 'all';
    self._searchText = '';
    self._injectPageShell();
    RPGACE.hooks.on('page:show', function(name) {
      var pageId = RPGACE.CONFIG && RPGACE.CONFIG.pages ? RPGACE.CONFIG.pages.chronicles : null;
      if (pageId && name === pageId) self._render();
    });
  },

  _injectPageShell: function() {
    var self = this;
    if (!RPGACE.CONFIG || !RPGACE.CONFIG.pages) return;
    var pageId = 'page-' + RPGACE.CONFIG.pages.chronicles;
    if (document.getElementById(pageId)) return;
    var app = document.getElementById('app');
    if (!app) return;

    var page = document.createElement('div');
    page.className = 'page';
    page.id = pageId;
    page.innerHTML =
      '<div class="section-title">📜 The Chronicles — Full Log</div>' +
      '<div id="chron-digest" style="display:none;font-size:11px;color:var(--muted);border:1px solid var(--border);border-radius:8px;padding:8px 12px;margin-bottom:12px;line-height:1.6;"></div>' +
      '<div id="chron-summary" style="display:flex;flex-wrap:wrap;gap:10px;margin-bottom:16px;"></div>' +
      '<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center;">' +
        '<input id="chron-search" type="text" placeholder="Search the log…" style="flex:1;min-width:180px;background:var(--panel2);border:1px solid var(--border);border-radius:8px;padding:8px 12px;color:var(--text);font-family:Rajdhani,sans-serif;font-size:13px;">' +
        '<button id="chron-add-btn" style="padding:8px 14px;background:var(--gold);border:none;border-radius:8px;color:#000;font-weight:700;font-size:12px;cursor:pointer;font-family:Rajdhani,sans-serif;">+ Log Sale / Expense</button>' +
      '</div>' +
      '<div id="chron-filters" style="display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap;"></div>' +
      '<div id="chron-list"></div>';
    app.appendChild(page);

    var searchInp = page.querySelector('#chron-search');
    searchInp.addEventListener('input', function() { self._searchText = searchInp.value.toLowerCase(); self._renderList(); });
    page.querySelector('#chron-add-btn').addEventListener('click', function() { self._showAddForm(); });
  },

  _renderFilterChips: function() {
    var self = this;
    var el = document.getElementById('chron-filters');
    if (!el) return;
    el.innerHTML = '';
    self.FILTERS.forEach(function(f) {
      var active = f === self._activeFilter;
      var b = document.createElement('button');
      b.textContent = self.FILTER_LABELS[f] || f;
      b.style.cssText = 'padding:5px 12px;border-radius:20px;font-size:11px;font-weight:700;cursor:pointer;font-family:Rajdhani,sans-serif;border:1px solid ' + (active ? 'var(--gold)' : 'var(--border)') + ';background:' + (active ? 'var(--gold)' : 'var(--panel2)') + ';color:' + (active ? '#000' : 'var(--muted)') + ';';
      b.onclick = function() { self._activeFilter = f; self._renderFilterChips(); self._renderList(); };
      el.appendChild(b);
    });
  },

  _render: function() {
    var self = this;
    var csc = RPGACE.modules.careerStatCard;
    if (!csc) return;
    csc._fetchAll().then(function(data) {
      var shipped = data.content.filter(function(r) { return csc._isShipped(r); });
      var ideas = data.content.filter(function(r) { return !csc._isShipped(r); });
      self._allItems = csc._buildItems(data, shipped, ideas);
      self._renderSummary(data.finance || []);
      self._renderFilterChips();
      self._renderList();
    }).catch(function(e) {
      console.warn('[RPGACE:chroniclesLog] render failed', e.message);
    });
    self._renderOversightDigest();
  },

  // Journal/Chronicles/oversight cross-feed idea, Alex-confirmed July 24:
  // "measured doses" on-open digest, sourced from all six oversight docs
  // (not just minotaur_map) - kept deliberately light. Fetches ONCE per
  // session (this project's own real freeze history came from repeated
  // re-fetches on every page:show - careerStatCard._fetchAll had exactly
  // this bug, fixed earlier), fails open/silent if any doc is unreachable,
  // and shows short excerpts only - no markdown parsing, no new dependency.
  _renderOversightDigest: function() {
    var self = this;
    var el = document.getElementById('chron-digest');
    if (!el) return;
    if (self._digestCache) { self._paintDigest(self._digestCache); return; }
    if (self._digestFetching) return;
    self._digestFetching = true;

    Promise.all([
      fetch('/CLAUDE.md').then(function(r) { return r.ok ? r.text() : null; }).catch(function() { return null; }),
      fetch('/patch_notes.html').then(function(r) { return r.ok ? r.text() : null; }).catch(function() { return null; }),
    ]).then(function(results) {
      var claudeMd = results[0], patchNotes = results[1];
      var lines = [];

      if (claudeMd) {
        var stateMatch = claudeMd.match(/^## Current state.*\n- (.+)$/m);
        if (stateMatch) lines.push('🧭 ' + stateMatch[1].replace(/\*\*/g, '').slice(0, 160));
      }
      if (patchNotes) {
        var cardMatch = patchNotes.match(/<div class="card-title">([^<]+)<\/div>/);
        if (cardMatch) lines.push('📋 Latest: ' + cardMatch[1].replace(/&amp;/g, '&').slice(0, 160));
      }

      self._digestCache = lines;
      self._digestFetching = false;
      self._paintDigest(lines);
    }).catch(function() { self._digestFetching = false; });
  },

  _paintDigest: function(lines) {
    var el = document.getElementById('chron-digest');
    if (!el || !lines || !lines.length) return;
    el.innerHTML = lines.map(function(l) { return '<div>' + l.replace(/</g, '&lt;') + '</div>'; }).join('');
    el.style.display = 'block';
  },

  _renderSummary: function(finance) {
    var el = document.getElementById('chron-summary');
    if (!el) return;
    var sales = finance.filter(function(r) { return r.type === 'sale'; });
    var expenses = finance.filter(function(r) { return r.type === 'expense'; });
    var totalSales = sales.reduce(function(s, r) { return s + Number(r.amount || 0); }, 0);
    var totalExpenses = expenses.reduce(function(s, r) { return s + Number(r.amount || 0); }, 0);
    var byCat = {};
    expenses.forEach(function(r) { var c = r.category || 'Other'; byCat[c] = (byCat[c] || 0) + Number(r.amount || 0); });
    var catLine = Object.keys(byCat).sort(function(a, b) { return byCat[b] - byCat[a]; })
      .map(function(c) { return c + ': £' + byCat[c].toFixed(2); }).join(' • ') || 'No expenses logged yet';

    function chip(label, val, color) {
      return '<div style="background:var(--panel2);border:1px solid var(--border);border-radius:8px;padding:10px 16px;text-align:center;min-width:110px">'
        + '<div style="font-family:Cinzel,serif;font-size:17px;color:' + color + '">' + val + '</div>'
        + '<div style="font-size:11px;color:var(--muted);letter-spacing:1px;text-transform:uppercase;margin-top:2px">' + label + '</div></div>';
    }
    el.innerHTML = chip('Total Sales', '£' + totalSales.toFixed(2), 'var(--green)')
      + chip('Total Expenses', '£' + totalExpenses.toFixed(2), 'var(--red)')
      + chip('Net', (totalSales - totalExpenses >= 0 ? '£' : '-£') + Math.abs(totalSales - totalExpenses).toFixed(2), 'var(--gold)')
      + '<div style="flex-basis:100%;font-size:11px;color:var(--muted);padding:4px 2px">Expenses by category: ' + catLine.replace(/</g, '&lt;') + '</div>'
      + '<div style="flex-basis:100%;font-size:11px;color:var(--muted);font-style:italic;padding:0 2px">Personal visibility tracker only — not bookkeeping-grade. Keep real receipts for actual tax filing.</div>';
  },

  _renderList: function() {
    var self = this;
    var listEl = document.getElementById('chron-list');
    if (!listEl || !self._allItems) return;
    var q = self._searchText;
    var filtered = self._allItems.filter(function(it) {
      if (self._activeFilter !== 'all' && it.type !== self._activeFilter) return false;
      if (q && it.label.toLowerCase().indexOf(q) === -1) return false;
      return true;
    });
    listEl.innerHTML = '';
    if (!filtered.length) {
      var empty = document.createElement('div');
      empty.style.cssText = 'font-size:12px;color:var(--muted);padding:20px 0;text-align:center';
      empty.textContent = 'Nothing matches yet.';
      listEl.appendChild(empty);
      return;
    }
    filtered.forEach(function(it) {
      var row = document.createElement('div');
      row.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 12px;border-bottom:1px solid var(--border);cursor:pointer;';
      row.onmouseenter = function() { row.style.background = 'var(--panel2)'; };
      row.onmouseleave = function() { row.style.background = 'transparent'; };
      var icon = document.createElement('span'); icon.style.fontSize = '14px'; icon.textContent = it.icon;
      var label = document.createElement('span'); label.style.cssText = 'flex:1;font-size:12px;color:var(--text);'; label.textContent = it.label;
      var date = document.createElement('span'); date.style.cssText = 'font-size:11px;color:var(--muted);'; date.textContent = RPGACE.modules.careerStatCard._relTime(it.t);
      row.appendChild(icon); row.appendChild(label); row.appendChild(date);
      row.onclick = function() { RPGACE.modules.careerStatCard._showDetail(it); };
      listEl.appendChild(row);
    });
  },

  _showAddForm: function() {
    var self = this;
    var dd = RPGACE.modules.dashDeck;
    if (!dd || !dd._popup) { console.warn('[RPGACE:chroniclesLog] dashDeck._popup unavailable'); return; }
    var pop = dd._popup({ eyebrow: '📜 The Chronicles', title: 'Log a real sale or expense', width: '480px', accent: 'var(--gold)' });
    var today = new Date().toISOString().slice(0, 10);
    var datalistOpts = self.CATEGORY_SUGGESTIONS.map(function(c) { return '<option value="' + c + '">'; }).join('');
    pop.box.innerHTML =
      '<div style="display:flex;flex-direction:column;gap:10px;">' +
        '<label style="font-size:11px;color:var(--muted)">Type<select id="cf-type" style="width:100%;margin-top:4px;padding:8px;background:var(--panel2);border:1px solid var(--border);border-radius:6px;color:var(--text);font-family:Rajdhani,sans-serif;">' +
          '<option value="expense">🧾 Expense (equipment, plugins, etc.)</option>' +
          '<option value="sale">💰 Sale (beat sold, drum kit sold, etc.)</option>' +
        '</select></label>' +
        '<label style="font-size:11px;color:var(--muted)">Date<input id="cf-date" type="date" value="' + today + '" style="width:100%;margin-top:4px;padding:8px;background:var(--panel2);border:1px solid var(--border);border-radius:6px;color:var(--text);font-family:Rajdhani,sans-serif;"></label>' +
        '<label style="font-size:11px;color:var(--muted)">Item<input id="cf-item" type="text" placeholder="e.g. Ableton Move, Custom drum kit" style="width:100%;margin-top:4px;padding:8px;background:var(--panel2);border:1px solid var(--border);border-radius:6px;color:var(--text);font-family:Rajdhani,sans-serif;"></label>' +
        '<label style="font-size:11px;color:var(--muted)">Category<input id="cf-category" type="text" list="cf-cat-list" placeholder="e.g. Equipment" style="width:100%;margin-top:4px;padding:8px;background:var(--panel2);border:1px solid var(--border);border-radius:6px;color:var(--text);font-family:Rajdhani,sans-serif;"><datalist id="cf-cat-list">' + datalistOpts + '</datalist></label>' +
        '<label style="font-size:11px;color:var(--muted)">Amount (£)<input id="cf-amount" type="number" min="0" step="0.01" placeholder="e.g. 149.99" style="width:100%;margin-top:4px;padding:8px;background:var(--panel2);border:1px solid var(--border);border-radius:6px;color:var(--text);font-family:Rajdhani,sans-serif;"></label>' +
        '<label style="font-size:11px;color:var(--muted)">Notes (optional)<textarea id="cf-notes" rows="2" style="width:100%;margin-top:4px;padding:8px;background:var(--panel2);border:1px solid var(--border);border-radius:6px;color:var(--text);font-family:Rajdhani,sans-serif;resize:vertical;"></textarea></label>' +
        '<div id="cf-error" style="color:#CC4A4A;font-size:11px;display:none;"></div>' +
        '<button id="cf-submit" style="padding:10px;background:var(--gold);border:none;border-radius:8px;color:#000;font-weight:700;font-size:13px;cursor:pointer;font-family:Rajdhani,sans-serif;">Save to Chronicles</button>' +
      '</div>';

    pop.box.querySelector('#cf-submit').onclick = function() {
      var g = function(id) { var el = pop.box.querySelector(id); return el ? el.value.trim() : ''; };
      var errEl = pop.box.querySelector('#cf-error');
      var item = g('#cf-item'), amountRaw = g('#cf-amount'), date = g('#cf-date');
      var amount = parseFloat(amountRaw);
      if (!item || !amountRaw || isNaN(amount) || amount < 0) {
        errEl.textContent = 'Item and a valid amount are required.';
        errEl.style.display = 'block';
        return;
      }
      var row = {
        type: g('#cf-type') || 'expense',
        entry_date: date || today,
        item: item,
        category: g('#cf-category') || 'Other',
        amount: amount,
        notes: g('#cf-notes') || null
      };
      RPGACE.sb.secureWrite('chronicles_finance', 'insert', row).then(function() {
        RPGACE.cache.clear('chronicles_finance');
        if (RPGACE.utils && RPGACE.utils.toast) RPGACE.utils.toast('✓ Logged to Chronicles', 'var(--gold)', 2200);
        pop.close();
        self._render();
      }).catch(function(e) {
        errEl.textContent = 'Save failed: ' + e.message;
        errEl.style.display = 'block';
      });
    };
  },

  // July 23 — folded into the dashDeck card grid, same popup pattern as
  // Oversight/Knowledge Gaps: a compact preview (top 5, same shared
  // _buildItems/detail-popup logic the dashboard feed and full log page
  // already use) plus a real button into the full #page-chronicles page.
  _openCard: function() {
    var self = this;
    var dd = RPGACE.modules.dashDeck;
    var csc = RPGACE.modules.careerStatCard;
    if (!dd || !dd._popup || !csc) return;
    var pop = dd._popup({ eyebrow: '📜 The Chronicles', title: 'Recent activity', accent: 'var(--gold)', width: '520px' });
    pop.box.innerHTML = '<div id="dd-chron-list" style="font-size:12px;color:var(--muted)">Loading…</div><button id="dd-chron-full" style="margin-top:14px;width:100%;padding:10px;background:var(--gold);border:none;border-radius:8px;color:#000;font-weight:700;font-size:13px;cursor:pointer;font-family:Rajdhani,sans-serif;">View Full Log →</button>';
    pop.box.querySelector('#dd-chron-full').onclick = function() {
      pop.close();
      if (typeof showPage === 'function') showPage(RPGACE.CONFIG.pages.chronicles);
    };
    csc._fetchAll().then(function(data) {
      var shipped = data.content.filter(function(r) { return csc._isShipped(r); });
      var ideas = data.content.filter(function(r) { return !csc._isShipped(r); });
      var items = csc._buildItems(data, shipped, ideas).slice(0, 5);
      var listEl = pop.box.querySelector('#dd-chron-list');
      if (!listEl) return;
      if (!items.length) { listEl.textContent = 'No real activity logged yet.'; return; }
      listEl.innerHTML = '';
      items.forEach(function(it) {
        var row = document.createElement('div');
        row.style.cssText = 'display:flex;gap:8px;align-items:center;padding:8px 0;border-bottom:1px solid var(--border);cursor:pointer;font-size:12px;color:var(--text);';
        row.innerHTML = '<span>' + it.icon + '</span><span style="flex:1">' + String(it.label).replace(/</g, '&lt;') + '</span><span style="color:var(--muted);font-size:11px">' + csc._relTime(it.t) + '</span>';
        row.onclick = function() { csc._showDetail(it); };
        listEl.appendChild(row);
      });
    }).catch(function(e) {
      var listEl = pop.box.querySelector('#dd-chron-list');
      if (listEl) listEl.textContent = 'Load failed: ' + e.message;
    });
  }
});
/* ===END:chroniclesLog=== */

/* ===MODULE:jargonEncyclopedia=== */
// July 22 — "biggest confirmed-not-built items" list (CLAUDE.md) named a
// Taxonomy Sorting Agent and a Jargon Encyclopedia as blocked on it. Real
// GODMODE finding before building anything: tracing the actual call chain
// (bookworm._decidePlacementScored -> phylumPath.decidePlacementScored,
// the exact same function encSync/ciAutoPropose already call) shows book
// and non-book inputs already share ONE placement engine - the July 19
// unification already did this. The Jargon Encyclopedia was never actually
// blocked on new agent logic, just on a read-only view existing at all.
// Built as a Postgres view (jargon_encyclopedia, security_invoker) over
// taxonomy_tree's real leaf rows - zero new writes, same live-query-every-
// load convention taxonomy_map.html already uses. Injected as a button
// into Phylum Path's EXISTING page shell (not a new nav entry/page) per
// Alex's explicit "build in to the existing rather than build on top."
RPGACE.register('jargonEncyclopedia', {
  init: function() {
    var self = this;
    RPGACE.hooks.on('page:show', function(name) {
      var pageId = RPGACE.CONFIG && RPGACE.CONFIG.pages ? RPGACE.CONFIG.pages.phylumPath : null;
      if (pageId && name === pageId) setTimeout(function() { self._injectButton(); }, 200);
    });
    setTimeout(function() { self._injectButton(); }, 2000);
  },

  _injectButton: function() {
    if (document.getElementById('jargon-enc-btn')) return;
    var title = document.getElementById('pp-phylum-title');
    if (!title || !title.parentNode) return;
    var self = this;
    var btn = document.createElement('button');
    btn.id = 'jargon-enc-btn';
    btn.textContent = '📖 Jargon Encyclopedia';
    btn.style.cssText = 'margin-bottom:10px;padding:6px 14px;background:var(--panel2);border:1px solid var(--border);border-radius:8px;color:var(--gold);font-size:12px;font-weight:700;cursor:pointer;font-family:Rajdhani,sans-serif;display:block;';
    btn.onclick = function() { self._openGlossary(); };
    title.insertAdjacentElement('afterend', btn);
  },

  _openGlossary: function() {
    var self = this;
    var dd = RPGACE.modules.dashDeck;
    if (!dd || !dd._popup) return;
    var pop = dd._popup({ eyebrow: '📖 Every leaf term across your tree', title: 'Jargon Encyclopedia', width: '640px', accent: 'var(--gold)' });
    pop.box.innerHTML = '<input id="jarg-search" type="text" placeholder="Search terms..." style="width:100%;margin-bottom:12px;padding:8px 12px;background:var(--panel2);border:1px solid var(--border);border-radius:8px;color:var(--text);font-family:Rajdhani,sans-serif;font-size:13px;"><div id="jarg-list" style="max-height:50vh;overflow-y:auto;">Loading…</div>';
    var listEl = pop.box.querySelector('#jarg-list');
    var searchInp = pop.box.querySelector('#jarg-search');
    RPGACE.sb.select('jargon_encyclopedia', 'select=name,path,explainer,phylum_number&order=name.asc&limit=1000').then(function(rows) {
      rows = rows || [];
      self._allTerms = rows;
      self._renderTerms(listEl, rows);
      searchInp.addEventListener('input', function() {
        var q = searchInp.value.toLowerCase();
        var filtered = rows.filter(function(r) { return (r.name || '').toLowerCase().indexOf(q) !== -1; });
        self._renderTerms(listEl, filtered);
      });
    }).catch(function(e) {
      listEl.textContent = 'Load failed: ' + e.message;
    });
  },

  _renderTerms: function(listEl, rows) {
    if (!rows.length) { listEl.innerHTML = '<div style="color:var(--muted);font-size:12px;padding:8px 0">No terms match.</div>'; return; }
    listEl.innerHTML = rows.map(function(r) {
      return '<div style="padding:8px 0;border-bottom:1px solid var(--border);">'
        + '<div style="font-size:13px;font-weight:700;color:var(--text);">' + String(r.name || '').replace(/</g, '&lt;') + '</div>'
        + '<div style="font-size:11px;color:var(--muted);margin-top:2px;">' + String(r.explainer || '').replace(/</g, '&lt;') + '</div>'
        + '</div>';
    }).join('');
  }
});
/* ===END:jargonEncyclopedia=== */

/* ===MODULE:pathRouter=== */
// July 23 — Alex: "make rpgace a multi-page URL." Real GODMODE finding
// before building: vercel.json's catch-all rewrite ("/(.*)" -> "/index.html")
// already serves index.html for ANY path today, so a real URL per page
// needs zero server-side change - purely client-side pushState routing on
// top of the existing showPage()/page:show wrap. Council of 5 deliberately
// DECOUPLED this from the bigger, separate "split rpgace_core.js into
// multiple files" ask - that's a much higher-risk refactor (~40
// interdependent modules, a fragile already-documented rpgace:ready timing
// pattern) held back for its own dedicated pass, not bundled in here.
RPGACE.register('pathRouter', {
  _syncingFromHistory: false,

  init: function() {
    var self = this;
    RPGACE.hooks.on('rpgace:login', function() { self._routeFromCurrentURL(); });
    RPGACE.hooks.on('page:show', function(name) { self._pushIfNeeded(name); });
    // NOTE: not `global.addEventListener` - this module is defined AFTER
    // the outer IIFE's own closing `})(window);` (line 510), so the IIFE's
    // `global` parameter is out of scope here entirely. Real bug found via
    // testing (the listener silently never attached, "global is not
    // defined" in the module-init failure log) - every other module past
    // that point correctly uses `window`/bare globals instead.
    window.addEventListener('popstate', function(e) {
      // Going back to the root URL (no page pushed onto that history
      // entry, e.g. the very first page load) has neither e.state.page
      // nor a recognizable path - falling through would silently leave
      // whatever page was already showing on screen, un-navigated.
      // Default to the dashboard in that case rather than doing nothing.
      var pages = RPGACE.CONFIG && RPGACE.CONFIG.pages;
      var name = (e.state && e.state.page) || self._slugFromPath(location.pathname) || (pages && pages.dashboard);
      if (!name) return;
      self._syncingFromHistory = true;
      if (typeof showPage === 'function') showPage(name);
      self._syncingFromHistory = false;
    });
  },

  _validSlugs: function() {
    var pages = RPGACE.CONFIG && RPGACE.CONFIG.pages;
    if (!pages) return [];
    return Object.keys(pages).map(function(k) { return pages[k]; });
  },

  _slugFromPath: function(pathname) {
    var slug = (pathname || '/').replace(/^\/+/, '').replace(/\/+$/, '');
    return this._validSlugs().indexOf(slug) !== -1 ? slug : null;
  },

  // Runs once, right after real login (never before - #app is hidden and
  // showPage() has nothing to act on pre-login). Reads whatever page the
  // URL already names (a bookmark, a shared link, a hard refresh on a
  // deep page) and shows it instead of always defaulting to the dashboard.
  _routeFromCurrentURL: function() {
    var slug = this._slugFromPath(location.pathname);
    if (slug && typeof showPage === 'function') {
      showPage(slug);
    } else {
      // No recognizable page in the URL (a fresh "/" visit) - dashboard is
      // already showing from the raw HTML default, but give this root
      // entry real state too, so a later "back" to it lands on a properly
      // recognized page instead of relying on the popstate fallback.
      var pages = RPGACE.CONFIG && RPGACE.CONFIG.pages;
      if (pages && pages.dashboard) {
        try { history.replaceState({ page: pages.dashboard }, '', location.pathname); } catch (e) {}
      }
    }
  },

  _pushIfNeeded: function(name) {
    if (this._syncingFromHistory) return;
    if (!name) return;
    var target = '/' + name;
    if (location.pathname === target) return;
    try { history.pushState({ page: name }, '', target); } catch (e) {}
  }
});
/* ===END:pathRouter=== */

/* ===MODULE:perfWatch=== */
// July 23 — real-evidence infra, not a fix. Alex reported the leftNav
// drawer's exit button and dashDeck popups' Close button "freeze" on his
// real phone/laptop, AFTER the request-storm dedup fix (careerStatCard
// _inflightFetch) already shipped. A synthetic Playwright pass (headless
// desktop AND mobile-viewport touch taps, real hit-testing via
// elementFromPoint at the button's exact screen coordinates) found the
// close handlers themselves wired correctly and instant in both cases —
// but that sandbox's network can't reach Supabase at all (every request
// fails instantly), so it cannot reproduce a REAL slow-network / real-CPU
// main-thread block the way Alex's actual device would. Per this file's
// own "one failed fix = stop, get real evidence, don't patch blind a
// second time" rule: rather than guess a second blind fix, this ships a
// passive PerformanceObserver('longtask') watcher — standard browser API,
// zero behavior change, fails silently where unsupported — that surfaces
// any real main-thread block over 500ms as BOTH a console.warn (for a
// plugged-in debug session) and a visible toast (since Alex is testing on
// a phone, not with devtools open). Next time the freeze recurs, it should
// self-report its own real duration instead of needing another guess.
RPGACE.register('perfWatch', {
  init: function() {
    try {
      if (typeof PerformanceObserver === 'undefined') return;
      var obs = new PerformanceObserver(function(list) {
        list.getEntries().forEach(function(entry) {
          if (entry.duration < 500) return;
          var ms = Math.round(entry.duration);
          console.warn('[RPGACE perfWatch] main thread blocked for ' + ms + 'ms', entry);
          try {
            if (RPGACE.utils && RPGACE.utils.toast) {
              RPGACE.utils.toast('⚠️ App froze for ' + ms + 'ms (logged)', '#CC4A4A', 4000);
            }
          } catch (e2) {}
        });
      });
      obs.observe({ type: 'longtask', buffered: true });
    } catch (e) {
      // 'longtask' unsupported on this browser (e.g. Safari) - silent,
      // this is diagnostic-only and must never itself break anything.
    }
  }
});
/* ===END:perfWatch=== */

/* ===MODULE:voiceInput=== */
// 2026-07-28 — Alex fractured his right hand and asked whether voice
// input was possible, both for talking to Claude Code (answer: yes,
// already solved with zero code — the phone/OS keyboard's own mic/
// dictation button works in any text field, including wherever he types
// to Claude Code) and inside RPGACE itself (this module). Real,
// buildable via the browser's native Web Speech API (SpeechRecognition)
// — free, zero new dependency, fits the zero-npm-runtime architecture.
// Honest limitation: Chrome (desktop + Android — what Alex uses
// throughout this session's own screenshots) supports this well;
// Firefox has no support at all, Safari's has historically been
// unreliable. Not a blocker for a single-user app used from Chrome, but
// stated plainly rather than assumed universal.
RPGACE.register('voiceInput', {

  _recognition: null,
  _listening: false,
  _baseText: '',
  _target: null,
  _lastFocusedField: null,

  // 2026-07-29 — Alex is working one-handed today (fractured hand, "aching
  // like no tomorrow") and asked to make everything as low-click as
  // possible while he works mostly by mic. The existing button only
  // dictated into Oracle chat specifically - generalized the same core
  // recognition logic (rule 8: one shared mechanism, not a copy per field)
  // to target WHATEVER text input/textarea last had focus, plus a single
  // persistent floating mic button (fixed, on every page, body-level per
  // the fixed-overlay convention) so he never has to hunt for a per-page
  // button before he can dictate into Beat Log/Journal/Encyclopedia/
  // anywhere else that takes free text.
  init: function() {
    var self = this;
    // Global function name, matching this exact row's existing sibling
    // buttons (oracleImageUpload()/sendChatWithImage(), both plain global
    // functions called via onclick= in the static HTML) rather than
    // introducing a different calling convention for one new button.
    window.toggleVoiceInput = function() { self.toggle(); };
    window.toggleVoiceInputGlobal = function() { self.toggleGlobal(); };

    document.addEventListener('focusin', function(e) {
      var t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA') && !t.disabled && !t.readOnly) {
        self._lastFocusedField = t;
      }
    });

    RPGACE.registerBootTask(function() { return self._injectFloatingButton(); });
  },

  _injectFloatingButton: function() {
    if (document.getElementById('vi-floating-btn')) return;
    var btn = document.createElement('button');
    btn.id = 'vi-floating-btn';
    btn.title = 'Voice input — dictates into whatever text field you last tapped';
    btn.textContent = '🎤';
    btn.style.cssText = 'position:fixed;bottom:24px;right:20px;width:52px;height:52px;border-radius:50%;background:#0c0c16;border:2px solid rgba(201,168,76,.5);color:var(--gold);font-size:22px;cursor:pointer;z-index:999999;box-shadow:0 6px 20px rgba(0,0,0,.5);';
    btn.onclick = function() { window.toggleVoiceInputGlobal(); };
    document.body.appendChild(btn);
  },

  _supported: function() {
    return !!(window.SpeechRecognition || window.webkitSpeechRecognition);
  },

  toggle: function() {
    if (!this._supported()) {
      RPGACE.utils.toast('🎤 Voice input isn\'t supported in this browser — try Chrome', '#CC4A4A', 3500);
      return;
    }
    if (this._listening) { this._stop(); return; }
    this._start(document.getElementById('chat-input'));
  },

  // Targets whatever text input/textarea last had real focus, so ONE
  // floating button works on every page/popup without per-field wiring.
  toggleGlobal: function() {
    if (!this._supported()) {
      RPGACE.utils.toast('🎤 Voice input isn\'t supported in this browser — try Chrome', '#CC4A4A', 3500);
      return;
    }
    if (this._listening) { this._stop(); return; }
    var field = this._lastFocusedField;
    if (!field || !document.body.contains(field)) {
      RPGACE.utils.toast('🎤 Tap into a text field first, then tap the mic', '#C9A84C', 3000);
      return;
    }
    this._start(field);
  },

  _start: function(input) {
    if (!input) return;
    this._target = input;
    this._listening = true;
    this._setButtonState(true);
    this._baseText = input.value ? input.value.replace(/\s+$/, '') + ' ' : '';
    this._spawnRecognizer(input);
  },

  // July 29 — first fix attempt (looping from e.resultIndex instead of 0)
  // did NOT resolve it: Alex confirmed, via a real reload-and-retest, that
  // the exact same compounding duplication ("can you" -> "can you can
  // you" -> ...) still happened. Real evidence this points to: Android
  // Chrome's SpeechRecognition implementation (what Alex uses) is known
  // to be far less spec-reliable than desktop Chrome specifically around
  // e.resultIndex and continuous-mode restarts - relying on the browser's
  // own "what's new" hint was the wrong foundation. This rewrite ignores
  // e.resultIndex entirely and tracks our OWN idempotency by array
  // position (_finalizedCount) instead - once e.results[i].isFinal is
  // true, that transcript is committed to _baseText exactly once, no
  // matter what the browser claims changed. Also spawns a genuinely NEW
  // SpeechRecognition object on every restart rather than reusing the
  // ended one - the standard, more robust pattern real SpeechRecognition
  // wrapper libraries use, since reusing an ended instance is undefined/
  // inconsistent behavior on some mobile implementations. Per this
  // project's own per-defect cap (CLAUDE.md rule 9 / Engineer skill): this
  // is the LAST attempt before stopping to get real console evidence
  // instead of guessing a third time.
  _spawnRecognizer: function(input) {
    var self = this;
    var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    var rec = new SR();
    rec.lang = 'en-GB';
    rec.continuous = true;
    rec.interimResults = true;
    this._finalizedCount = 0;

    rec.onresult = function(e) {
      var interimText = '';
      for (var i = 0; i < e.results.length; i++) {
        if (e.results[i].isFinal) {
          if (i >= self._finalizedCount) {
            self._baseText += e.results[i][0].transcript + ' ';
            self._finalizedCount = i + 1;
          }
        } else if (i >= self._finalizedCount) {
          interimText += e.results[i][0].transcript;
        }
      }
      input.value = self._baseText + interimText;
      input.dispatchEvent(new Event('input', { bubbles: true }));
    };
    rec.onerror = function(e) {
      RPGACE.utils.toast('🎤 Voice input error: ' + (e.error || 'unknown'), '#CC4A4A', 3000);
      self._stop();
    };
    rec.onend = function() {
      // Chrome auto-stops recognition after a silence gap even in
      // continuous mode — restart transparently (with a FRESH recognizer,
      // see note above) while still toggled on, so a fractured-hand user
      // isn't stuck re-tapping the button after every pause in speech.
      if (self._listening) { try { self._spawnRecognizer(input); } catch (e2) {} }
    };

    this._recognition = rec;
    try {
      rec.start();
    } catch (e) {
      RPGACE.utils.toast('🎤 Could not start: ' + e.message, '#CC4A4A', 3000);
      this._listening = false;
      this._setButtonState(false);
    }
  },

  _stop: function() {
    this._listening = false;
    if (this._recognition) { try { this._recognition.stop(); } catch (e) {} this._recognition = null; }
    this._setButtonState(false);
  },

  _setButtonState: function(active) {
    var btn = document.getElementById('voice-input-btn');
    if (btn) {
      btn.textContent = active ? '🔴' : '🎤';
      btn.title = active ? 'Stop voice input' : 'Voice input';
      btn.style.borderColor = active ? '#CC4A4A' : 'rgba(201,168,76,.3)';
      btn.style.color = active ? '#CC4A4A' : 'var(--gold)';
    }
    var fbtn = document.getElementById('vi-floating-btn');
    if (fbtn) {
      fbtn.textContent = active ? '🔴' : '🎤';
      fbtn.title = active ? 'Stop voice input' : 'Voice input — dictates into whatever text field you last tapped';
      fbtn.style.borderColor = active ? '#CC4A4A' : 'rgba(201,168,76,.5)';
      fbtn.style.color = active ? '#CC4A4A' : 'var(--gold)';
    }
  },

});
/* ===END:voiceInput=== */

/* ===MODULE:mockOracle=== */
// Aug 6 (Alex out of real Anthropic credits, real "test the wiring without
// Oracle actually thinking" ask) — a real, honest fake-Oracle mode. Every
// reply generated this way is unmistakably labeled (rule 7 - fail loud,
// never silently indistinguishable from a real response), and the ONLY
// thing it replaces is the actual network call inside callOracle() in
// main.js (see the comment there) - every real button click, DOM update,
// hook fire (oracle:response-scanned), Supabase write, and trailer-parse
// (_saveDocToProduction's DIRECTOR_CHOSEN:/EDL_JSON: regexes) still runs
// authentically on top of the fake text, so this genuinely exercises real
// app wiring end-to-end without spending real API tokens. Off by default,
// zero DOM footprint when off (matches the no-post-login-pop-in
// convention every other module here follows).
RPGACE.register('mockOracle', {

  // Aug 6, same day, 2nd pass: extended from a binary Dummy/Real switch to
  // a real 3-state Oracle Mode, per Alex's own direct spec ("in the toggle
  // in top right as a third mode. think of those oracle functions as
  // modes"). MODE_KEY replaces the old binary STORAGE_KEY; the old key is
  // migrated once in init() and never written again, so no dangling second
  // source of truth survives (rule 8). isEnabled() is kept as the exact
  // same method name/meaning ("is Dummy mode active") specifically because
  // main.js's callOracle() already calls it - zero change needed at that
  // call site for the dummy-mode branch.
  MODE_KEY: 'rpgace_oracle_mode',
  LEGACY_KEY: 'rpgace_mock_oracle',
  MODES: ['real', 'dummy', 'fallback'],

  init: function() {
    var self = this;
    try {
      if (!localStorage.getItem(this.MODE_KEY) && localStorage.getItem(this.LEGACY_KEY) === '1') {
        localStorage.setItem(this.MODE_KEY, 'dummy');
        localStorage.removeItem(this.LEGACY_KEY);
      }
    } catch (e) {}
    RPGACE.registerBootTask(function() { return self._injectToggleButton(); });
    RPGACE.registerBootTask(function() { return self._injectScoutButton(); });
  },

  getMode: function() {
    try {
      var m = localStorage.getItem(this.MODE_KEY);
      return this.MODES.indexOf(m) !== -1 ? m : 'real';
    } catch (e) { return 'real'; }
  },
  setMode: function(mode) {
    if (this.MODES.indexOf(mode) === -1) return;
    try { localStorage.setItem(this.MODE_KEY, mode); } catch (e) {}
    if (mode === 'dummy') {
      RPGACE.utils.toast('🧪 Dummy Oracle ON — every Oracle reply from now on is fake, wiring-test only. No real API calls, no real cost.', '#E2A83D', 5000);
    } else if (mode === 'fallback') {
      RPGACE.utils.toast('📥 Fallback Scout Mode ON — every Oracle send now queues for later, free, instead of calling the real API. Open "Scouted" any time to browse answers.', 'rgba(201,168,76,0.9)', 6000);
    } else {
      RPGACE.utils.toast('✅ Real Oracle API — live calls resume', '#4CAF82', 3000);
    }
    this._renderState();
  },
  // Back-compat: "isEnabled" has always meant "is Dummy mode active" -
  // main.js's callOracle() calls this exact method name/meaning already.
  isEnabled: function() { return this.getMode() === 'dummy'; },
  isFallbackMode: function() { return this.getMode() === 'fallback'; },
  // Cycles Real -> Dummy -> Fallback -> Real on click.
  toggle: function() {
    var order = ['real', 'dummy', 'fallback'];
    var next = order[(order.indexOf(this.getMode()) + 1) % order.length];
    this.setMode(next);
  },

  // Real reply generator, called from main.js's callOracle() when mock
  // mode is on. Scans the outbound prompt for this app's own known
  // structured trailers (DIRECTOR_CHOSEN:, EDL_JSON:) so downstream
  // parsing genuinely gets exercised, not just the chat bubble text -
  // same real trailer names visualOracle._saveDocToProduction already
  // looks for, kept in sync by reading the same literal strings rather
  // than a second guessed format (rule 8).
  _fakeReply: function(messages, system, onChunk) {
    var lastUser = (messages || []).slice().reverse().filter(function (m) { return m.role === 'user'; })[0];
    var promptText = ((system || '') + ' ' + (lastUser && lastUser.content || '')).toLowerCase();

    var lines = [
      '🧪 [MOCK ORACLE — no real API call made, wiring test only]',
      '',
      'This is a synthetic stand-in reply while real Anthropic credits are unavailable. It exists to exercise real button/DOM/Supabase wiring end-to-end, not to represent real output quality — never treat this text as a genuine Oracle answer.',
    ];
    if (promptText.indexOf('director_chosen') !== -1) {
      lines.push('', 'DIRECTOR_CHOSEN: Christopher Nolan');
    }
    if (promptText.indexOf('edl_json') !== -1) {
      lines.push('', 'EDL_JSON: [{"scene":1,"start":0,"end":4,"desc":"[MOCK] establishing shot — wiring test only"}]');
    }
    var full = lines.join('\n');

    return new Promise(function (resolve) {
      if (onChunk) {
        // Feed it back progressively so the real streaming-render path
        // (renderMarkdown, chat-box scroll behaviour) gets exercised too,
        // not just the final-result path.
        var parts = full.match(/[\s\S]{1,40}/g) || [full];
        var i = 0, acc = '';
        var iv = setInterval(function () {
          acc += parts[i] || '';
          onChunk(acc);
          i++;
          if (i >= parts.length) {
            clearInterval(iv);
            resolve({ content: [{ type: 'text', text: acc }] });
          }
        }, 55);
      } else {
        setTimeout(function () {
          resolve({ content: [{ type: 'text', text: full }] });
        }, 400 + Math.random() * 400);
      }
    });
  },

  // Aug 6 (real hand-test report: "i cant see dummy oracle right now...
  // it is not there") — replaced the small bottom-right circular button
  // (competing for space/attention with voiceInput's own floating mic
  // button, easy to miss) with a real, always-visible toggle switch fixed
  // at the top of the page. Alex's own exact spec: red track = Dummy
  // Oracle, click, slides to green = Oracle API. Unlike the old design
  // (which only showed a warning banner while mock mode was ON), this
  // switch is permanently rendered regardless of state — the discoverability
  // complaint was the real bug, not the toggle logic itself, so the fix is
  // "always there," not "smarter hiding."
  // Widened to a 3-position track same day (2nd pass) for the Fallback
  // mode: Real -> Dummy -> Fallback -> Real, cycling on click, per Alex's
  // own spec ("in the toggle in top right as a third mode").
  _injectToggleButton: function () {
    if (document.getElementById('mock-oracle-switch')) return;
    var self = this;

    var wrap = document.createElement('div');
    wrap.id = 'mock-oracle-switch';
    wrap.title = 'Click to cycle Oracle Mode: Real API → Dummy (wiring tests, zero cost) → Fallback Scout (queue for free later answers)';
    wrap.style.cssText = 'position:fixed;top:10px;right:10px;z-index:999999;display:flex;align-items:center;gap:8px;background:#0c0c16;border:1px solid rgba(255,255,255,0.15);border-radius:20px;padding:5px 12px 5px 5px;box-shadow:0 4px 16px rgba(0,0,0,.5);cursor:pointer;font-family:Rajdhani,sans-serif;user-select:none;';

    var track = document.createElement('div');
    track.id = 'mock-oracle-track';
    track.style.cssText = 'position:relative;width:64px;height:24px;border-radius:12px;flex-shrink:0;transition:background .2s ease;';

    var knob = document.createElement('div');
    knob.id = 'mock-oracle-knob';
    knob.style.cssText = 'position:absolute;top:2px;left:2px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.4);transition:left .2s ease;';
    track.appendChild(knob);

    var label = document.createElement('span');
    label.id = 'mock-oracle-label';
    label.style.cssText = 'font-size:12px;font-weight:700;letter-spacing:.5px;white-space:nowrap;';

    wrap.appendChild(track);
    wrap.appendChild(label);
    wrap.onclick = function () { self.toggle(); };
    document.body.appendChild(wrap);
    self._renderState();
  },

  // Small pill next to the switch, opening the "Scouted, Now Answered"
  // browsable list. Always present (not just while Fallback mode is
  // active) since past scouted items stay worth browsing regardless of
  // which mode is active right now.
  _injectScoutButton: function () {
    if (document.getElementById('mock-oracle-scout-btn')) return;
    var self = this;
    var btn = document.createElement('div');
    btn.id = 'mock-oracle-scout-btn';
    btn.title = 'Browse scouted questions and their free fallback answers';
    btn.style.cssText = 'position:fixed;top:44px;right:10px;z-index:999999;background:#0c0c16;border:1px solid rgba(201,168,76,0.35);border-radius:14px;padding:4px 11px;font-size:11px;font-weight:700;letter-spacing:.3px;color:rgba(201,168,76,0.9);cursor:pointer;font-family:Rajdhani,sans-serif;user-select:none;box-shadow:0 3px 10px rgba(0,0,0,.4);';
    btn.textContent = '📥 Scouted';
    btn.onclick = function () { self._openScoutedList(); };
    document.body.appendChild(btn);
  },

  _renderState: function () {
    var track = document.getElementById('mock-oracle-track');
    var knob = document.getElementById('mock-oracle-knob');
    var label = document.getElementById('mock-oracle-label');
    var existingBadge = document.getElementById('mock-oracle-badge');
    if (existingBadge) existingBadge.remove();
    if (!track || !knob || !label) return;

    var mode = this.getMode();
    if (mode === 'dummy') {
      // Dummy Oracle active — red, knob left.
      track.style.background = '#CC4A4A';
      knob.style.left = '2px';
      label.textContent = '🧪 Dummy Oracle';
      label.style.color = '#CC4A4A';
      // Still keep a real full-width warning strip while active (rule 7 —
      // a corner switch alone is easy to miss mid-scroll on a long chat
      // reply). Sits just under the switch, same z-tier convention.
      var badge = document.createElement('div');
      badge.id = 'mock-oracle-badge';
      badge.textContent = '🧪 DUMMY ORACLE ON — every reply is fake, wiring-test only';
      badge.style.cssText = 'position:fixed;top:0;left:0;right:0;background:#CC4A4A;color:#1a0808;font-weight:700;font-size:12px;text-align:center;padding:6px 10px;z-index:999998;font-family:Rajdhani,sans-serif;letter-spacing:0.5px;';
      document.body.appendChild(badge);
    } else if (mode === 'fallback') {
      // Fallback Scout mode active — amber/gold, knob center.
      track.style.background = 'rgba(201,168,76,0.85)';
      knob.style.left = '22px';
      label.textContent = '📥 Fallback Scout';
      label.style.color = '#C9A84C';
      var badge2 = document.createElement('div');
      badge2.id = 'mock-oracle-badge';
      badge2.textContent = '📥 FALLBACK SCOUT MODE — every send is queued, not answered live. Check "Scouted" for answers.';
      badge2.style.cssText = 'position:fixed;top:0;left:0;right:0;background:rgba(201,168,76,0.9);color:#1a1508;font-weight:700;font-size:12px;text-align:center;padding:6px 10px;z-index:999998;font-family:Rajdhani,sans-serif;letter-spacing:0.5px;';
      document.body.appendChild(badge2);
    } else {
      // Real Oracle API — green, knob right.
      track.style.background = '#4CAF82';
      knob.style.left = '42px';
      label.textContent = '✅ Oracle API';
      label.style.color = '#4CAF82';
    }
  },

  // ── Fallback Scout mode — real behavior ─────────────────────────────
  // Called from main.js's callOracle() when getMode()==='fallback',
  // exactly parallel to _fakeReply's dummy-mode call site. Instead of
  // fabricating an answer, this queues the REAL prompt into
  // oracle_fallback_queue (same table, same RPGACE.sb.secureWrite write
  // path phylumPath._queueFallback already uses — rule 8, no second
  // write mechanism invented) with a new context.type:'scout_item'
  // discriminator, then returns an honest, unmistakably-labeled
  // acknowledgment — never a fake answer to the actual question asked.
  // The daily "RPGACE Fallback Drain" Routine (already live, unchanged)
  // answers these the same way it answers every other tier; Alex browses
  // real answers later via _openScoutedList(), never an auto-injected
  // chat reply (the browser tab/session may be long gone by the time a
  // daily-batch answer lands).
  //
  // Aug 6 (2nd pass, real /deduplication ask): a real, generic dedup
  // check runs BEFORE every insert — any caller that fires the exact
  // same prompt twice (the concrete case that surfaced this:
  // generateEncBullets() re-queuing an encyclopedia entry's preview-
  // bullet prompt on every page reload, since ENC_BULLET_CACHE alone
  // never persisted — see main.js's own fix for that specific root
  // cause) gets told it's already queued instead of minting a second
  // row. This is deliberately caller-agnostic (matches on prompt text
  // alone, not on which module queued it) so it protects every current
  // and future Fallback Scout caller the same way, per rule 8.
  _queueScoutItem: function (messages, system, onChunk) {
    var self = this;
    var lastUser = (messages || []).slice().reverse().filter(function (m) { return m.role === 'user'; })[0];
    var promptText = (lastUser && lastUser.content) || '';

    var row = {
      prompt: promptText,
      tier: 'ground_worker_text',
      max_tokens: 1500,
      model: null,
      status: 'pending',
      context: { type: 'scout_item', queued_via: 'live_chat_fallback_mode', system: system || null }
    };

    // Fail loud (rule 7): a failed write must never come back looking
    // like a successful queue — this is checked explicitly rather than
    // swallowed, unlike a bare .catch(warn-and-continue) would produce.
    var ackLines = function (pendingCount, writeFailed, writeErr, wasDuplicate) {
      if (writeFailed) {
        return [
          '⚠️ [SCOUT QUEUE WRITE FAILED — this question was NOT saved]',
          '',
          'Real error: ' + (writeErr || 'unknown'),
          '',
          'Nothing was queued. Switch back to Real or Dummy mode, or try again — do not assume this was captured.',
        ].join('\n');
      }
      var lines = wasDuplicate ? [
        '♻️ [ALREADY SCOUTED — /deduplication caught an exact repeat, nothing new queued]',
        '',
        'This exact question is already sitting in your scouting queue — a second identical row was NOT created, so it won\'t be reanalysed twice for no reason. Check "📥 Scouted" for its real answer once the daily drain runs.',
      ] : [
        '📥 [SCOUTED — queued for free fallback processing, not answered live]',
        '',
        'This question was added to your scouting queue instead of calling the real API. It will be answered by the daily Fallback Drain (free, uses Claude Code\'s own access, no Anthropic API spend) — check "📥 Scouted" any time to browse real answers as they land.',
      ];
      lines.push('', 'Pending in queue: ' + pendingCount);
      if (pendingCount >= 10) {
        lines.push('', '🔔 10+ items waiting — the next daily drain will answer all of them. This app can\'t auto-fire the drain early from the browser (real limitation, not a bug) — ask a Claude Code session to fire it now if you want them answered sooner.');
      }
      return lines.join('\n');
    };

    var respond = function (pendingCount, writeFailed, writeErr, wasDuplicate) {
      var full = ackLines(pendingCount, writeFailed, writeErr, wasDuplicate);
      return new Promise(function (resolve) {
        if (onChunk) {
          var parts = full.match(/[\s\S]{1,40}/g) || [full];
          var i = 0, acc = '';
          var iv = setInterval(function () {
            acc += parts[i] || '';
            onChunk(acc);
            i++;
            if (i >= parts.length) {
              clearInterval(iv);
              resolve({ content: [{ type: 'text', text: acc }] });
            }
          }, 55);
        } else {
          setTimeout(function () { resolve({ content: [{ type: 'text', text: full }] }); }, 300);
        }
      });
    };

    // Fetch existing pending scout_item prompts (not just IDs) so an
    // exact repeat can be caught client-side before inserting - avoids
    // putting the full (up to ~3000+ char) prompt text into a URL
    // filter, which real long entries would make unreliable.
    return RPGACE.sb.select('oracle_fallback_queue', "context->>type=eq.scout_item&status=eq.pending&select=prompt&order=created_at.desc&limit=50")
      .catch(function () { return []; })
      .then(function (existingRows) {
        var pending = existingRows || [];
        var duplicate = pending.some(function (r) { return r.prompt === promptText; });
        if (duplicate) {
          return respond(pending.length, false, null, true);
        }
        var writeFailed = false, writeErr = null;
        return RPGACE.sb.secureWrite('oracle_fallback_queue', 'insert', [row])
          .catch(function (e) { writeFailed = true; writeErr = e.message; console.warn('[mockOracle] scout enqueue failed:', e.message); })
          .then(function () {
            return respond(writeFailed ? pending.length : pending.length + 1, writeFailed, writeErr, false);
          });
      });
  },

  // "📥 Scouted, Now Answered" — real browsable list, confirms Q1 from the
  // earlier /paranoia interrogation round. Reads oracle_fallback_queue
  // directly (anon_all RLS, never restricted — same landmine-protected
  // table _checkFallbackAnswers already reads), newest first, showing
  // both still-pending and already-answered scout_item rows so Alex can
  // see the real state of his own queue, not just a black box.
  _openScoutedList: function () {
    var self = this;
    var pop = RPGACE.modules.dashDeck._popup({
      dim: '0.92', scroll: true, width: '640px', borderColor: 'rgba(201,168,76,0.35)',
      eyebrow: 'Fallback Scout Mode', title: '📥 Scouted, Now Answered', accent: 'rgba(201,168,76,0.9)',
    });
    var body = pop.box;
    var loading = document.createElement('div');
    loading.style.cssText = 'color:var(--muted);font-size:12px;padding:10px 0;';
    loading.textContent = 'Loading scouted items…';
    body.appendChild(loading);

    RPGACE.sb.select('oracle_fallback_queue', "context->>type=eq.scout_item&order=created_at.desc&limit=50")
      .then(function (rows) {
        loading.remove();
        if (!rows || !rows.length) {
          var empty = document.createElement('div');
          empty.style.cssText = 'color:var(--muted);font-size:12px;padding:10px 0;';
          empty.textContent = 'Nothing scouted yet. Switch the top-right toggle to 📥 Fallback Scout and send an Oracle message to queue your first item.';
          body.appendChild(empty);
          return;
        }
        rows.forEach(function (row) {
          var card = document.createElement('div');
          card.style.cssText = 'border:1px solid var(--border);border-radius:8px;padding:12px 14px;margin-bottom:10px;';
          var answered = row.status === 'answered';
          var statusChip = document.createElement('span');
          statusChip.style.cssText = 'display:inline-block;font-size:10px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;padding:2px 8px;border-radius:10px;margin-bottom:8px;' + (answered ? 'background:rgba(76,175,130,0.15);color:#4CAF82;' : 'background:rgba(201,168,76,0.15);color:#C9A84C;');
          statusChip.textContent = answered ? '✅ Answered' : '⏳ Pending';
          card.appendChild(statusChip);

          var promptEl = document.createElement('div');
          promptEl.style.cssText = 'font-size:12px;color:var(--text);white-space:pre-wrap;margin-bottom:' + (answered ? '8px' : '0') + ';';
          promptEl.textContent = row.prompt || '(no prompt text)';
          card.appendChild(promptEl);

          if (answered && row.answer) {
            var ansLbl = document.createElement('div');
            ansLbl.style.cssText = 'font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:rgba(76,175,130,0.7);margin:8px 0 4px;';
            ansLbl.textContent = 'Real answer';
            card.appendChild(ansLbl);
            var ansEl = document.createElement('div');
            ansEl.style.cssText = 'font-size:12px;color:var(--muted);white-space:pre-wrap;';
            ansEl.textContent = row.answer;
            card.appendChild(ansEl);
          }
          body.appendChild(card);
        });
      })
      .catch(function (e) {
        loading.textContent = 'Could not load scouted items: ' + e.message;
      });
  },

});
/* ===END:mockOracle=== */

/* ===MODULE:oracleProviderMode=== */
// G34 of the ratified "RPGACE Total Systems Galaxy Map" /CEO plan (Aug
// 15 2026), Level 1 only — a real, separate axis from mockOracle's own
// Real/Dummy/Fallback toggle (that one picks WHETHER a real network call
// happens at all; this one picks WHICH real provider answers when it
// does). Alex's own confirmed spec: "Level 1 (Y/N): local Claude vs
// external provider (Moonshot/Luna, dormant, honest-labeled)." Level 2
// (a real Fable/Opus dev-role indicator) is a real, separate, deliberately
// NOT-yet-built piece — Alex is typing down his own real spec for it
// next; this module and its UI leave real room for that (see the
// comment on _injectToggleButton below) without guessing its shape.
//
// Real, load-bearing landmine avoided (found by reading api/oracle.js
// directly, not assumed): the server's `provider` branch runs BEFORE the
// `stream` branch and always returns a plain JSON blob, never SSE — so
// external-provider mode always sends `stream:false`, even from a caller
// that normally streams. main.js's callOracle() forwards the real final
// text to onChunk ONCE at the end when this happens, so a streaming
// caller's UI still renders correctly, just without the word-by-word
// animation (an honest, deliberate UX difference for this mode, not a
// silent bug).
RPGACE.register('oracleProviderMode', {

  MODE_KEY: 'rpgace_oracle_provider',
  // Real, dormant free-tier providers this can route to — same real
  // FREE_TIER_PROVIDERS keys api/oracle.js already defines (rule 8, not
  // re-derived; kept in sync by hand since this is a client-side mirror
  // of a server-side object, same pattern already accepted for
  // SKILL_RIVER-style small constants elsewhere in this codebase).
  PROVIDERS: ['kimi', 'luna'],
  PROVIDER_KEY: 'rpgace_oracle_provider_choice',

  init: function() {
    var self = this;
    RPGACE.registerBootTask(function() { return self._injectToggleButton(); });
  },

  getMode: function() {
    try { return localStorage.getItem(this.MODE_KEY) === 'external' ? 'external' : 'local'; }
    catch (e) { return 'local'; }
  },
  isExternal: function() { return this.getMode() === 'external'; },
  getProviderName: function() {
    try {
      var p = localStorage.getItem(this.PROVIDER_KEY);
      return this.PROVIDERS.indexOf(p) !== -1 ? p : 'kimi';
    } catch (e) { return 'kimi'; }
  },
  setProviderName: function(p) {
    if (this.PROVIDERS.indexOf(p) === -1) return;
    try { localStorage.setItem(this.PROVIDER_KEY, p); } catch (e) {}
    this._renderState();
  },
  toggle: function() {
    var next = this.isExternal() ? 'local' : 'external';
    try { localStorage.setItem(this.MODE_KEY, next); } catch (e) {}
    if (next === 'external') {
      RPGACE.utils.toast('🌐 External provider mode ON (' + this.getProviderName() + ') — dormant until a real API key is configured server-side; a send will fail loud with an honest error until then.', '#4A90E2', 5500);
    } else {
      RPGACE.utils.toast('🔮 Local Oracle (Claude) — real calls resume', '#4CAF82', 3000);
    }
    this._renderState();
  },
  // Right-click cycles which dormant provider is targeted (kimi/luna) —
  // deliberately a secondary interaction, not a 3rd toggle track, since
  // neither is live yet and this keeps the pinned-toggle row uncluttered
  // ahead of Alex's own real Level 2 spec landing on top of this module.
  cycleProvider: function() {
    var i = this.PROVIDERS.indexOf(this.getProviderName());
    this.setProviderName(this.PROVIDERS[(i + 1) % this.PROVIDERS.length]);
    RPGACE.utils.toast('Target provider: ' + this.getProviderName(), '#4A90E2', 2000);
  },

  _injectToggleButton: function() {
    if (document.getElementById('oracle-provider-switch')) return;
    var self = this;
    // Real, deliberate stacking: mock-oracle-switch (top:10px), mock-
    // oracle-scout-btn (top:44px), this one (top:78px) — same pinned
    // top-right column, same visual language (pill/track/knob), never
    // merged into the existing switch since this is a genuinely
    // different real axis (WHICH provider, not WHETHER a call happens).
    var wrap = document.createElement('div');
    wrap.id = 'oracle-provider-switch';
    wrap.title = 'Click: toggle Local Claude ↔ External provider (dormant). Right-click: cycle target provider (kimi/luna).';
    wrap.style.cssText = 'position:fixed;top:78px;right:10px;z-index:999999;display:flex;align-items:center;gap:8px;background:#0c0c16;border:1px solid rgba(255,255,255,0.15);border-radius:20px;padding:5px 12px 5px 5px;box-shadow:0 4px 16px rgba(0,0,0,.5);cursor:pointer;font-family:Rajdhani,sans-serif;user-select:none;';

    var track = document.createElement('div');
    track.id = 'oracle-provider-track';
    track.style.cssText = 'position:relative;width:44px;height:24px;border-radius:12px;flex-shrink:0;transition:background .2s ease;';
    var knob = document.createElement('div');
    knob.id = 'oracle-provider-knob';
    knob.style.cssText = 'position:absolute;top:2px;left:2px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.4);transition:left .2s ease;';
    track.appendChild(knob);

    var label = document.createElement('span');
    label.id = 'oracle-provider-label';
    label.style.cssText = 'font-size:12px;font-weight:700;letter-spacing:.5px;white-space:nowrap;';

    wrap.appendChild(track);
    wrap.appendChild(label);
    wrap.onclick = function() { self.toggle(); };
    wrap.oncontextmenu = function(e) { e.preventDefault(); self.cycleProvider(); };
    document.body.appendChild(wrap);
    self._renderState();
  },

  _renderState: function() {
    var track = document.getElementById('oracle-provider-track');
    var knob = document.getElementById('oracle-provider-knob');
    var label = document.getElementById('oracle-provider-label');
    if (!track || !knob || !label) return;
    if (this.isExternal()) {
      track.style.background = '#4A90E2';
      knob.style.left = '22px';
      label.textContent = '🌐 ' + this.getProviderName();
      label.style.color = '#4A90E2';
    } else {
      track.style.background = 'rgba(255,255,255,0.15)';
      knob.style.left = '2px';
      label.textContent = '🔮 Local';
      label.style.color = 'rgba(226,226,236,0.7)';
    }
  },

});
/* ===END:oracleProviderMode=== */

/* ===MODULE:errorLog=== */
// Real, minimal client-side error capture (Aug 12 2026), per Alex's own
// ask for "a new oversight doc, it logs all error that rpgace total
// systems ever sees... all ai and code send error code to a supabase
// table." Genuinely different from the same-day CEO-pill mistake this
// module sits right where that used to be: error telemetry is a
// standard, real part of a shipped app's OWN code (capturing what
// actually goes wrong while Alex is using RPGACE), not a development-
// process concept - it belongs here the same way it would in any
// production web app. Deliberately minimal for this first real slice:
// global window.onerror/unhandledrejection only. Per-API-endpoint
// server-side error capture (api/*.js) is real, scoped future work, not
// built blind in this pass - see CLAUDE.md's Open forks.
RPGACE.register('errorLog', {

  init: function() {
    var self = this;
    window.addEventListener('error', function(e) {
      self._capture('js_runtime', (e.filename || 'unknown') + ':' + (e.lineno || '?'), e.message || (e.error && e.error.message) || String(e.error || 'unknown error'));
    });
    window.addEventListener('unhandledrejection', function(e) {
      var msg = (e.reason && (e.reason.message || String(e.reason))) || 'unhandled promise rejection';
      self._capture('js_promise', 'unhandledrejection', msg);
    });
  },

  // Real, same-method normalized-key dedup as intelDedup already proves
  // in production (rule 8) - strips ids/numbers so the SAME real error
  // recurring with a different row id/count in its message still
  // dedupes onto one row instead of minting a new one every time.
  _signature: function(type, source, message) {
    var norm = String(message || '').replace(/[0-9a-f-]{8,}/gi, '<id>').replace(/\d+/g, '<n>').slice(0, 200);
    return (type + '|' + (source || '') + '|' + norm).slice(0, 300);
  },

  _capture: function(type, source, message) {
    var sig = this._signature(type, source, message);
    RPGACE.sb.select('error_log', 'error_signature=eq.' + encodeURIComponent(sig) + '&status=eq.active&limit=1')
      .then(function(rows) {
        if (rows && rows.length) {
          return RPGACE.sb.update('error_log', 'id=eq.' + rows[0].id, {
            occurrence_count: (rows[0].occurrence_count || 1) + 1,
            last_seen_at: new Date().toISOString(),
          });
        }
        return RPGACE.sb.insert('error_log', {
          error_signature: sig,
          error_type: type,
          source: source,
          message: String(message).slice(0, 2000),
          status: 'active',
        });
      }).catch(function() {
        // Fail silent, deliberately - an error-LOGGING failure must
        // never itself throw a second, louder error in front of Alex.
      });
  },

});
/* ===END:errorLog=== */
